(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["tr"] = {"ui":{"lead":"Oyunlar nasıl bulundu, unutuldu, çözüldü ve değişti? {n} hikâyeyi okuyun; sondaki testte tüm soruları doğru yanıtlayan bir damga kazanır.","card":"Damga kartı","cardN":"{of} damgadan {n} toplandı","cardAll":"Hepsi toplandı!","no":"Hikâye {n}","mins":"{n} dk","stamped":"Damgalandı","back":"Tüm hikâyeler","quiz":"Kısa test","links":"Gör ve oyna","game":"Oyun","exhibit":"Koleksiyon","art":"Resim","room":"Salon","room_chance":"Şans","qn":"Soru {n} / {of}","right":"Doğru!","wrong":"Olmadı — doğru cevap işaretlendi.","got":"Damgalandı!","again":"Hepsi doğru!","gotSub":"Damga kartınıza işlendi.","missed":"{n} yanlış","retrySub":"Damga için tüm soruları doğru yanıtlayın. Hikâyeyi yeniden okuyup tekrar deneyin.","retry":"Tekrar dene","room_paint":"Sanatta","room_map":"Harita","kfH":"Öne çıkanlar","tlH":"Zaman çizelgesi","refH":"Kaynaklar ve okumalar","picLink":"müzenin sayfasını açar"},"ex":{"ur":"Ur Kraliyet Oyunu tahtası","liubo":"Liubo tahtası ve taşları","pyrgus":"Roma zar kulesi","sugoroku":"Shōsōin sugoroku tahtası","nishapur":"Nişabur satranç takımı","lewis":"Lewis satranç taşları","senet":"Tutankamon’un senet kutusu","ballinderry":"Ballinderry oyun tahtası","goose":"Satranç ve kaz oyunu tahtası","kofukuji":"Kōfuku-ji’den çıkan shogi taşları","shosoin":"Shōsōin go tahtası"},"paint":{"liubo":"Liubo oynayan iki figür","sugoroku":"Sugoroku oynayan iki kız","shahnama":"Büzürgmihr satrancı çözüyor","nefertari":"Senet oynayan Kraliçe Nefertari","chaupar":"Çaupar oynayan Şiva ve Parvati","shogi":"Shogi oynayan genç çift","hydria":"Tahta oyunu oynayan Akhilleus ve Aias (su testisi)","eakins":"Satranç Oyuncuları","weiqi":"Weiqi oynayan ölümsüzler tabağı","webb":"Tavla oynayanlar (dolap)","liberale":"Satranç Oynayanlar","mirror":"Satranç oynayan çiftli ayna kabı","morris":"Bir oyun tahtası (dokuz taş)","leifeng":"Leifeng Pagodası oyun tahtası","teniers":"Tavla oyunu","imari":"Go oynayan iki adamlı tabak","shoei":"Dört Hüner","tutinama":"Maymun satranç arkadaşı prensi ısırıyor (Babür, 1560 dolayları)"},"ur":{"title":"4500 yıllık bir oyun kurallarını nasıl geri buldu","lead":"Ur kraliyet mezarlarından çıkan tahtanın talimatı yoktu. İpucu iki bin yıl sonra yazılmış bir kil tablettedi.","s":["1920’lerde Leonard Woolley, güney Irak’taki Ur’da kraliyet mezarlarını kazdı ve deniz kabuğu ile lapis lazuli kakmalı, yirmi kareli bir tahta buldu; MÖ 2600–2400 dolaylarına aittir. Benzer tahtalar bütün Orta Doğu’da bulundu: oyun uzun süre ve yaygın biçimde oynanmıştı.","Ama oyunun nasıl oynandığını anlatan hiçbir şey onlarla birlikte çıkmadı. Tahta, taşlar, zarlar — ve hiç kural yok: eski oyunlarda sık görülen bir durum.","İpucu British Museum’un depolarındaydı: Babilli kâtip Itti-Marduk-balāṭu’nun MÖ 177/176’da Iddin-Bēl adlı birinin tabletinden kopyaladığı çivi yazılı bir tablet. Tahtadan iki bin yıldan fazla sonra yazılmıştı.","1980’lerin başında British Museum’dan Irving Finkel, tabletin aynı yirmi kareli oyunu anlattığını fark etti. Arka yüzünde tahta ve üzerine gelinen karelere ait kehanetler yer alıyordu. Finkel, tabletten ve tahtanın kendisinden yola çıkarak iki kişilik bir yarış oyunu kurguladı.","Onun yeniden kurgusu bugün dünyanın her yerinde oynanıyor. Ur’da tam olarak böyle oynanıp oynanmadığını kimse bilemez. Yine de güney Hindistan’daki Koçi’de benzer bir oyun 1950’lere dek oynanıyordu — bu oyunun ne kadar uzun yaşadığının bir işareti."],"quiz":[["Kuralları veren tablet ne zaman yazıldı?","MÖ 2. yüzyılda, tahtadan 2000 yıldan fazla sonra","Tahtayla aynı, MÖ 2600 dolayında","Orta Çağ’da (12. yüzyıl)","19. yüzyılda"],["Tableti çözüp kuralları yeniden kuran kimdir?","Irving Finkel","Howard Carter","Jean-François Champollion","Arthur Evans"],["Tablet, karelere gelince ne söylüyor?","Kehanetler — iyi ya da kötü talih","Kral adları","Vergi miktarları","Yalnızca yıldız adları"]],"kf":["Tahtalar MÖ 2600–2400 dolaylarına aittir; güney Irak’taki Ur’un kraliyet mezarlarından çıktı","Kurallar 2000 yıldan fazla sonra yazılmış bir kil tabletten yeniden kuruldu","20 hane, her tarafa yedi taş, dört yüzlü zarlar"],"more":[{"h":"Kraliyet mezarları ve “kraliyet oyunu”","p":["Woolley, Ur’un Kraliyet Mezarlığı’nda tek değil, birkaç yirmi haneli tahta buldu. En ünlüsü, bugün British Museum’da, deniz kabuğu, kırmızı kireçtaşı ve lapis lazuli kakmalı ahşaptır; oyuna “Ur’un Kraliyet Oyunu” adını veren de odur.","Yine de yalnız kralların oyunu değildi. Aynı tahtalar Mezopotamya’dan Mısır’a ve Doğu Akdeniz’e kadar bulunur; bir Asur sarayında, kapıyı bekleyen insan başlı kanatlı dev boğa heykelinin kaidesine — anlaşılan nöbetçiler tarafından — bir tahta bile kazınmıştır."],"cap":["British Museum’daki Ur’un Kraliyet Oyunu — Koleksiyon odasında 3D olarak çevirebilirsin"]},{"h":"Tahtanın yapısı","p":["Yirmi hane, 12’lik (3×4) ve 6’lık (3×2) iki bloğun 2 hanelik dar bir “köprü”yle birleşmesinden oluşur. Beş hanede gül motifi vardır; yeniden kurulan kurallarda buraya gelen bir kez daha atar ve burada taşı alınamaz.","Zarlar, dört ucundan ikisi işaretli dörtyüzlülerdir. Dördü birden atılır, yukarı bakan işaretli uç sayısı kadar ilerlenir: 0’dan 4’e. En sık 2 gelir (16’da 6); 0 ve 4 ise 16’da yalnızca bir kez. Müzenin “Şans” odasında bunları atabilirsin."],"cap":["Yirmi hane ve beş gül motifi. Yeşil sayılar bir oyuncunun haneden haneye yolu (yeniden kurulan kurallar)","Dört dörtyüzlü zarın düşüşleri (eşit olasılıklı 16 durumdan)"]},{"h":"Tablet ne anlatıyor","p":["Tabletin ön yüzü oyunu anlatır; arka yüzünde haneleri burç işaretli bir tahta çizimi vardır. Hanelere ait sözler kehanet gibidir — “bir dost bulacaksın”, “iyi bira içeceksin” — yani oyun talihle bağlantılıydı.","Ancak tabletin bir kısmı kırıktır ve kuralların hepsi okunamaz. Finkel, okunabilen satırlarla tahtanın biçiminden en tutarlı oyunu kurdu; başka araştırmacılar farklı yorumlar önerdi."]},{"h":"Son oyuncular Hindistan’da","p":["Finkel sonradan, güney Hindistan’daki Koçi (Cochin) Yahudi topluluğunun yakın zamana kadar çok benzer biçimli bir tahtada yirmi haneli bir oyun oynadığını öğrendi.","Oyun, topluluk 1950’lerde İsrail’e göçene dek evlerde kuşaktan kuşağa aktarıldı. Belki eski ticaret yollarıyla Hindistan’a ulaşıp dört bin yıldan uzun yaşadı."]}],"tl":[["MÖ y. 2600–2400","Yirmi haneli tahtalar Ur’un kraliyet mezarlarına konur"],["MÖ 8. yüzyıl","Bir Asur sarayında kapı bekçisi heykelinin kaidesine tahta kazınır"],["MÖ 177/176","Babilli bir yazıcı kural tabletini kopyalar"],["1922–1934","Woolley Ur’u kazar ve tahtaları bulur"],["1980’lerin başı","Finkel tableti okuyup kuralları yeniden kurar"],["1950’lere kadar","Güney Hindistan’da Koçi’de çok benzer bir oyun oynanır"]]},"liubo":{"title":"Liubo neden yok oldu?","lead":"Han döneminde imparatordan halka herkes oynuyordu. Birkaç yüzyılda kuralları bile unutuldu.","s":["Liubo, Han Çin’inin (MÖ 206 – MS 220) büyük tutkusuydu. Mezar figürlerinde, taş kabartmalarda, hatta ayna süslemelerinde görülür; ölümsüzler sık sık liubo oynarken tasvir edilir.","Han’ın yıkılmasından sonra liubo hızla geriledi ve görünüşe göre Tang döneminde kuralları çoktan kaybolmuştu. Nedeni belli değil; bir görüşe göre oyuncular weiqi (go) gibi başka oyunlara yöneldi.","Geriye tahtalar ve araçlar kaldı. Tahtalarda T, L ve V biçimlerinden oluşan kendine özgü bir desen vardır; hamleler muhtemelen ince çubuklar atılarak belirlenirdi. Aynı desen, TLV aynaları denen aynaları da süsler.","Yazılı ipuçları da yavaş yavaş birikiyor. 1993’te Jiangsu’daki Yinwan Han mezarında tahta şemasını kullanan bir fal metni bulundu. 2010’larda kazılan Haihun Markisi Liu He’nin mezarından liubo ile ilgili binden fazla bambu şerit çıktı; incelemeler sürüyor.","Atlas’taki liubo bu ipuçlarına dayanan bir yeniden kurgudur. Araştırmacılar oyunu biraz farklı biçimlerde kurguluyor ve gerçek kurallar hâlâ tam bilinmiyor — yeni buluntular oynanışı değiştirebilir."],"quiz":[["Liubo hangi hanedan döneminde çok popülerdi?","Han","Ming","Qing","Song"],["Liubo ile ilgili binden fazla bambu şerit nerede bulundu?","Haihun Markisi Liu He’nin mezarında","İlk İmparator’un anıt mezarında","Dunhuang mağaralarında","Yasak Şehir’de"],["Liubo’da hamleyi belirlemek için muhtemelen ne atılırdı?","İnce çubuklar","Yirmi yüzlü bir zar","Bir topaç","Resimli kartlar"]],"kf":["Savaşan Devletler’den Han’a (MÖ 5. yy – MS 3. yy) Çin’de çok popülerdi","T, L ve V biçimli çizgileri olan bir tahta; hamle için ince çubuklar atılırdı","Han yıkılınca hızla unutuldu; kuralları bugün bile tam bilinmiyor"],"more":[{"h":"TLV tahtası","p":["Liubo tahtası karedir; ortada bir kare, her kenarın ortasında T, çevresinde L ve köşelerde V biçimli çizgiler vardır. Taşların bu çizgilerin üzerinde ve aralarında ilerlediği düşünülür.","Aynı çizgiler ayna sırtlarında (“TLV aynaları”) ve güneş saatlerinde de görülür. Bazı araştırmacılar tahtayı gök, yer ve dört yönü gösteren bir evren haritası olarak okur; liubo yalnızca eğlence değildi."],"cap":["Bir liubo tahtasının çizgileri (TLV deseni): ortada kare, her kenarda T, köşelere doğru L ve V"]},{"h":"Nasıl oynanırdı","p":["Araştırmacıların çoğuna göre her oyuncunun altı taşı vardı ve hamle ince bambu çubuklar atılarak belirlenirdi. Adındaki “altı” (liu) bu altı çubuktan ya da altı taştan gelir.","İlerleyen bir taş güçlü bir “baykuş”a (xiao) dönüşüyordu anlaşılan. MÖ 3. yüzyıl dolaylarından Chu Şarkıları’ndaki “Ruhu Çağırma” şiirinde “baykuş olup bastırır, ‘beş beyaz!’ diye bağırırlar” dizesi vardır. Metinler, tahtanın ortasındaki “su”da “balık” tutulan bir oynayışı da anlatır."],"cap":["Bir Han mezarı için yapılmış, liubo oynayan iki figür (Metropolitan Sanat Müzesi)"]},{"h":"Mezarlardan çıkan takımlar","p":["Hunan, Changsha’daki Mawangdui 3 numaralı mezarında (MÖ y. 168) lake bir kutu içinde tahta, taşlar ve çubuklardan oluşan eksiksiz bir takım bulundu; ölü öteki dünyada da oynayabilsin diye konmuştu.","Mezar duvarlarındaki kabartmalarda, dağ tepelerinde liubo oynayan ölümsüzler sık sık görülür. Oyun, ölümsüzler ve uzun ömür dünyasıyla bağlantılıydı."],"cap":["Müzenin liubo tahtası — Koleksiyon odasında 3D olarak görebilirsin"]}],"tl":[["MÖ 5.–3. yy (Savaşan Devletler)","Liubo tahtaları mezarlara konmaya başlar"],["MÖ y. 3. yy","“Ruhu Çağırma” bir liubo oyununu anlatır"],["MÖ y. 168","Mawangdui 3 numaralı mezara eksiksiz bir takım konur"],["MÖ 206 – MS 220 (Han)","İmparatorlardan halka herkes oynar; kabartmalarda ve aynalarda"],["Tang (7.–10. yy)","Kuralların çoktan unutulduğu düşünülür"],["1993","Yinwan Han mezarlarından tahtayla fal bakılan bir metin çıkar"],["2010’lar","Haihun markisi Liu He’nin mezarında liubo bambu yazıtları bulunur"]]},"zeno":{"title":"İmparator Zenon’un şanssız zarı","lead":"Bin beş yüz yıl önce bir imparator zar attı — ve sonuç bir şiirde bugüne ulaştı.","s":["Romalılar, 24 haneli bir tahtada zarla oynanan bir yarış oyunu olan tabulayı severdi: tavlanın atası. Hileli atışları önlemek için zarların içinden yuvarlandığı zar kuleleri bile kullanılırdı.","480 dolaylarında Doğu Roma imparatoru Zenon tabula oynuyordu. Üç zarı 2, 5 ve 6 geldi. Kuralların gerektirdiği gibi oynamaktan başka çaresi yoktu ve tahtasında yalnız ve korumasız sekiz pul kaldı.","Oyunu, Zenon’dan birkaç on yıl sonra yaşamış 6. yüzyıl tarihçisi ve şairi Agathias kaydetti. Kısa şiiri (bir epigram) pulların yerlerini bile verir: antik bir oyunun nadir bir kaydı.","19. yüzyılda Fransız bilgin Becq de Fouquières, şiirden pozisyonu ve kuralları çıkardı: her oyuncuya on beş pul ve üç zar. Tüm pullar tahtanın dışından başlar ve iki oyuncu da aynı yöne ilerler.","Bugünkü tavlaya göre tabula üç zarla oynanır, tahtada hiç pul olmadan başlar ve katlama zarı yoktur. Bir imparatorun şanssızlığı sayesinde tabulanın neye benzediğini biliyoruz."],"quiz":[["Zenon’un zarları ne geldi?","2, 5 ve 6","6, 6 ve 6","1, 1 ve 1","3, 4 ve 5"],["Oyunu bir şiirle kaydeden kimdir?","Agathias","Homeros","Plinius","Cicero"],["Tabula ile bugünkü tavla arasındaki farklardan biri hangisi?","Tabula üç zarla oynanırdı","Her oyuncuya otuz pul","12 haneli bir tahta","Pullar geriye gider"]],"kf":["Tabula 24 hane ve üç zarla oynanırdı — tavlanın atası","İmparator Zenon’un 480 dolaylarındaki oyunu, konumuyla birlikte bir şiirde yaşıyor","Romalılar hileye karşı “zar kuleleri” bile yaptı"],"more":[{"h":"Tabula tahtası","p":["Tabula tahtası, bugünkü tavla gibi 12’şerli iki sırada 24 haneden oluşur. Her oyuncunun on beş taşı vardı ve başta hepsi tahtanın dışındaydı; üç zara göre girilir, tahta dolaşılır ve dışarı çıkılırdı.","Tavladan en büyük farkı, iki oyuncunun da aynı yöne gitmesidir. Tek başına duran taş, rakip onun hanesine gelirse vurulur ve yeniden girmek zorunda kalırdı. Zenon’un sekiz taşı tam da böyle açık taşlardı."],"cap":["Bir tabula tahtası: 12’şerli iki sırada 24 hane; iki oyuncunun taşları da aynı yöne (ok) gider"]},{"h":"Hileye karşı bir alet","p":["Romalılar zara bayılırdı. Kumar yasaktı ve söylendiğine göre yalnızca kışın Saturnalia bayramında serbestti — ama bahis hiç durmadı, zarla el çabukluğu da.","Zar kulesi bu yüzden vardı: Üstten atılan zarlar içerideki tahtalara çarpıp alttan yuvarlanarak çıkar. Almanya’da bir villada bulunan 4. yüzyıla ait kulenin üzerinde “Piktler yenildi, düşman yok edildi — gönül rahatlığıyla oynayın” yazısı oyulmuştur."],"cap":["Vettweiß-Froitzheim zar kulesi (4. yy) — Koleksiyon odasında 3D olarak görebilirsin"]},{"h":"İmparatorlar ve zarlar","p":["Yalnız Zenon değil. Tarihçi Suetonius’a göre 1. yüzyıldaki İmparator Claudius zara o kadar düşkündü ki bu sanat üzerine bir kitap yazdı ve oynarken tahta kaymasın diye arabasını düzenletti.","Roma kalıntılarında, altışar harfli kelimelerle dizilmiş 36 harfli pek çok tahta da çıkar; her harf bir hane işi görürdü, bazılarında “Kalk, oynamayı bilmiyorsun; bir oyuncuya yer aç” gibi takılmalar vardır."],"cap":["Tavla ve zar, imparatorlardan askerlere herkesin eğlencesiydi (Şans odasında küp zar atabilirsin)"]}],"tl":[["1. yy","İmparator Claudius zar oyunu üzerine bir kitap yazar"],["4. yy","Almanya’da bir villada zar kulesi kullanılır"],["y. 480","İmparator Zenon’un talihsiz oyunu"],["6. yy","Agathias oyunu şiire döker"],["y. 10. yy","Şiir Yunan Antolojisi’ne girer"],["1869","Becq de Fouquières konumu ve kuralları çözer"],["1934","R. G. Austin Zenon’un oyununu ayrıntılı yeniden inceler"]]},"sugoroku":{"title":"Yasaklanan sugoroku","lead":"Hükümdarlar yasakladı, halk oynamaya devam etti. Antik çağdan Edo dönemine Japonya’da tahta sugoroku’nun hikâyesi.","s":["Shōsōin hazinesi, rivayete göre İmparator Shōmu’nun çok sevdiği bir sugoroku tahtasını saklar. Bu, resimli kâğıt sugoroku değil, tahta üzerinde beyaz ve siyah taşların ilerletildiği ban-sugoroku’dur: tavlanın akrabası.","Sugoroku erkenden kumarla ilişkilendirildi. Nihon Shoki’ye göre İmparatoriçe Jitō onu 689’da yasakladı.","757’de yürürlüğe giren Yōrō Kanunu da keşişlerin ve rahibelerin sugoroku oynamasını yasaklıyordu. Yasaklar tekrar tekrar çıkarıldı; demek ki uyulmuyordu.","Heian döneminde de sugoroku sevildi; Yastık Kitabı’nda ve Genji’nin Hikâyesi’nde geçer. Heike Monogatari’ye göre emekli imparator Shirakawa, söz geçiremediği üç şey saymıştı: Kamo Nehri’nin suları, sugoroku zarları ve Hiei Dağı’nın savaşçı keşişleri.","Edo dönemi baskıları, evde ban-sugoroku oynayan genç kızları hâlâ gösterir. Ama Meiji dönemine gelindiğinde tahta oyunu neredeyse kaybolmuş, “sugoroku” resimli kâğıt oyunun adı olmuştu."],"quiz":[["Shōsōin tahtası gibi ban-sugoroku hangi oyunun akrabasıdır?","Tavla","Shogi","Go","İskambil"],["Nihon Shoki’ye göre sugoroku’yu 689’da kim yasakladı?","İmparatoriçe Jitō","İmparator Shōmu","İmparator Kanmu","İmparator Meiji"],["Shirakawa, Kamo Nehri ve savaşçı keşişlerin yanı sıra neye söz geçiremiyordu?","Sugoroku zarlarına","Shogi taşlarına","Go taşlarına","Bir kemari topuna"]],"kf":["Ban-sugoroku tavlanın akrabasıdır; Japonya’da 7. yüzyılda oynanıyordu","Kumar yüzünden defalarca yasaklandı; ilki 689’da İmparatoriçe Jitō","Meiji döneminde neredeyse unutuldu; “sugoroku” kâğıt resimli oyunun adı oldu"],"more":[{"h":"Shōsōin tahtası","p":["Shōsōin’deki tahta, fildişi ve boyalı ahşapla ince kakmalar yapılmış gül ağacındandır. Her yanda on iki, toplam 24 hanesi ve ortadaki bölmede çiçekleri vardır.","Shōsōin’de camdan ve taştan pek çok sugoroku taşı da saklanır. Ban-sugoroku on beş beyaz, on beş siyah taş ve iki zarla oynanır — tavlayla neredeyse aynı takım. Oyunun İran nardından Çin yoluyla geldiği düşünülür."],"cap":["Shōsōin’in kakma gül ağacından sugoroku tahtası — Koleksiyon odasında üzerinde oynayabilirsin"]},{"h":"Nasıl oynanır","p":["Her oyuncu on beş taşı belirli bir düzende dizer ve iki zara göre ilerler. Beyaz ve siyah zıt yönlerde döner; bütün taşlarını önce son altı haneye toplayan kazanır.","Tek başına duran taş vurulup başlangıca gönderilebilir. İki veya daha fazla taşlı haneye rakip giremez; ustalık, kapı kurmaktır. Koleksiyon odasında Shōsōin tahtasında bu şekilde oynayabilirsin."],"cap":["Bir ban-sugoroku tahtası (şema): 24 hane, beyaz ve siyah zıt yönlere gider"]},{"h":"Yasaklar ve modalar","p":["Jitō’dan sonra sugoroku daha pek çok kez yasaklandı; çünkü kumar yüzünden her şeyini kaybedenler hiç eksik olmadı. Kamakura şogunluğu da sugoroku bahsine karşı yasalar çıkardı.","Öte yandan soyluların bir hüneriydi de. Güzel bir tahta gelinin çeyizine girer, Edo döneminde gösterişli lake tahtalar yapılırdı. Kumar aleti diye sevilmeyen, hazine diye sevilen ban-sugoroku’nun iki yüzü vardı."],"cap":["Edo dönemi bir resimde ban-sugoroku (Resimlerdeki Oyunlar odası)"]}],"tl":[["7. yy","Ban-sugoroku Çin’den gelir"],["689","İmparatoriçe Jitō sugorokuyu yasaklar (Nihon shoki)"],["8. yy","Kakma tahta Shōsōin’e girer"],["757","Yōrō kanunu keşiş ve rahibelere yasaklar"],["Heian dönemi","Yastık Kitabı ve Genji’nin Hikâyesi’nde geçer"],["12. yy","Shirakawa’nın “sugoroku zarları” yakınması (Heike Hikâyesi)"],["Edo dönemi","Çeyiz için gösterişli tahtalar yapılır"],["Meiji dönemi","Ban-sugoroku neredeyse hiç oynanmaz olur"]]},"queen":{"title":"Satrançta vezir nasıl en güçlü taş oldu","lead":"Bugünün en güçlü taşı, başlangıçta çapraz yalnızca bir kare gidebilen bir danışmandı.","s":["Satranç Hindistan’dan İran’a ve Arap dünyasına geçti. Fars destanı Şehname’de bilge Büzürgmihr, Hindistan’dan gönderilen satranç bilmecesini çözer. O tahtalarda şahın yanında duran taş ferz, yani vezirdi.","Ferz yalnızca çapraz bir kare gidebiliyordu — çok zayıf bir taş. İran’daki Nişabur’dan gelen 12. yüzyıl satranç takımında, şahınkinden küçük bir taht biçimindedir.","Satranç Avrupa’ya ulaşınca vezir bir kraliçeye dönüştü; 12. yüzyıl Lewis taşları arasında kraliçeler vardır. Ama yeni ad hareketi değiştirmedi: taş zayıf kaldı.","Büyük değişim 15. yüzyıl sonunda İspanya’da geldi. 1475 dolaylarında Valensiya’da yazılmış Scachs d’amor (“Aşk satrancı”) adlı şiir, yatay, dikey ve çaprazda istediği kadar ilerleyen modern vezirin en eski kaydı sayılır. Ardından Lucena (1497) ve Damiano (1512) kitapları yeni kuralı Avrupa’ya yaydı.","Vezirin neden bu kadar güçlendiği kesin değil. Kimine göre daha hızlı oyunlar istendi; kimileri I. İsabel gibi güçlü kraliçelerin etkisini öne sürer. Her hâlükârda bu değişim satrancı bugünkü oyuna çok yaklaştırdı."],"quiz":[["Fars ve Arap satrancında bugünkü vezirin yerindeki taş hangisiydi?","Ferz (danışman)","Fil","Savaş arabası","At"],["İlk ferz nasıl hareket ederdi?","Çapraz bir kare","Düz çizgide istediği kadar","İki kare atlardı","Hareket edemezdi"],["Modern vezirin en eski kaydını içeren şiir nerede yazıldı?","Valensiya’da, 15. yüzyıl","Hindistan’da, 6. yüzyıl","Lewis’te, 12. yüzyıl","Londra’da, 19. yüzyıl"]],"kf":["Vezirin atası, çaprazlama yalnızca bir kare gidebilen Fars ve Arap “fers”iydi (danışman)","Bugünkü güçlü vezir ilk kez 1475 dolaylarında İspanya’da yazıya geçti","Basılı kitaplar yeni kuralları birkaç on yılda Avrupa’ya yaydı"],"more":[{"h":"Zayıf danışman","p":["Fers yalnızca çaprazlama bir kare gidebiliyordu; tahtanın bir ucundan öbürüne koşan bugünkü vezirden çok farklıydı. O zamanki satranç yavaştı, bir oyun saatler sürebilirdi.","Fil de yalnızca çaprazlama ikinci kareye sıçrardı. Son sıraya varan piyon terfi ederdi — ama yalnızca bu zayıf fers’e."],"cap":["Fers (solda) ve bugünkü vezirin (sağda) gidebildiği yerler"]},{"h":"“Vezir satrancı” ve “çılgın satranç”","p":["Yeni vezir ortaya çıkınca İspanya’da bu oyuna “vezir satrancı”, İtalya’da ise sertliğinden ötürü “çılgın satranç” (scacchi alla rabbiosa) dendi. Aynı sıralarda fil de çaprazlama istediği kadar kayabilir oldu.","Taşlar güçlenince oyun hızlanıp sertleşti. Birkaç hamlede kazanan tuzaklar ve sabit açılış dizileri üzerine kitaplar çıktı; satranç incelenen bir oyuna dönüştü."],"cap":["Liberale da Verona, Satranç Oynayanlar (1475 dolayları) — yeni vezirin doğduğu sıralarda yapıldı"]},{"h":"Neden kraliçe?","p":["Danışmanın neden kraliçeye dönüştüğü kesin değil. Şahın yanında duran taşı onun eşi saymak belki doğal geldi. Latincede “fers” “fercia” oldu, sonra taşa “regina”, yani kraliçe dendi.","Neden güçlendiği de tartışmalı: oyunu hızlandırmak için, ya da Kastilya Kraliçesi I. Isabel gibi güçlü kraliçelerin çağı olduğu için. Tarihçi Marilyn Yalom bu değişimi Orta Çağ’da kadınların konumuyla ilişkilendirdi."],"cap":["Lewis satranç taşlarından kraliçe (12. yy) — hâlâ eski, zayıf hareketiyle"]}],"tl":[["y. 6. yy","Hindistan’da satrancın atası çaturanga doğar"],["7.–9. yy","İran ve Arap dünyasında oynanır; şahın yanında fers vardır"],["y. 10. yy","Satranç Avrupa’ya ulaşır"],["12. yy","Lewis taşları arasında kraliçeler vardır (hâlâ zayıf)"],["y. 1475","Valensiya şiiri Scachs d’amor yeni hareketi anlatır"],["1497","Lucena’nın satranç kitabı İspanya’da basılır"],["1512","Damiano’nun kitabı İtalya’da çıkar, kurallar yayılır"]]},"senet":{"title":"Senet nasıl öte dünyaya bir yolculuk oldu","lead":"Mısır’da yaklaşık üç bin yıl oynanan bir oyun, sonunda ruhun ölümden sonraki yolculuğunu simgeledi.","s":["Senet, taşların üç sıra on kareden oluşan bir tahtada ilerlediği eski bir Mısır oyunudur. MÖ 3100 dolaylarına ait I. Hanedan mezarlarında senet tahtası olabilecek parçalar bulunmuştur. Krallar görkemli kutularda, sıradan insanlar taşa kazınmış tahtalarda oynardı.","Adı “geçiş” anlamına gelir. Yeni Krallık’tan (MÖ 1550 dolayından) itibaren senet, ölen kişinin ruhunun öte dünyadan geçiş yolculuğuyla ilişkilendirildi.","Ölüler Kitabı’nın 17. bölümünde ölen kişi görünmez bir rakiple senet oynar. II. Ramses’in eşi Nefertari’nin mezar duvarında da kraliçe bir senet tahtasının başında oturur.","Tutankamon’un mezarında en az beş oyun kutusu vardı. Bunlardan biri, abanoz ve fildişinden büyük bir kutu, üstünde senet, öbür yüzünde yirmi kareli başka bir oyun taşır.","Ama kuralları eksiksiz anlatan bir metin bulunamadı. 20. yüzyılda Jéquier, Bell ve Kendall (1978) gibi araştırmacılar tahtalardan, resimlerden ve metin parçalarından her biri bir oynanış yolu kurguladı. Atlas’taki senet de araştırmaya dayanan bu yollardan biridir."],"quiz":[["“Senet” adı ne anlama gelir?","Geçiş","Kralın oyunu","Otuz ev","Nehri geçmek"],["Yeni Krallık’ta senet neyle ilişkilendirildi?","Ruhun öte dünyadan geçiş yolculuğuyla","Yağmur dualarıyla","Savaş planlarıyla","Hasat kehanetiyle"],["Tutankamon’un mezarında en az kaç oyun kutusu vardı?","Beş","Bir","İki","Yüz"]],"kf":["Dünyanın en eski tahta oyunlarından: taşlar 3 × 10 haneli bir tahtada yarışır","Adı “geçmek” demektir; Yeni Krallık’ta ruhun öteki dünyadan geçiş yolculuğuyla özdeşleşti","Kurallar günümüze kalmadı; bugünkü oynanışlar 20. yüzyıl yeniden kurulumlarıdır"],"more":[{"h":"Otuz hane ve özel haneler","p":["Senet tahtasında onar haneli üç sıra, yani otuz hane vardır. Taşların ilk sırada soldan sağa, ikincide sağdan sola, üçüncüde yine soldan sağa giderek bir S çizdiği düşünülür.","Son beş haneye çoğu zaman özel işaretler çizilirdi. 26. hane “güzel ev”, 27. hane “su”dur; çoğu yeniden kurulumda suya düşen taş geri döner. 28–30. hanelerde sayılar ya da öteki dünyanın tanrıları vardı."],"cap":["Bir senet tahtası. Taşlar S çizerek ilerler; son beş hanede (26–30) özel işaretler vardır"]},{"h":"Atma çubuklarıyla ilerlemek","p":["Zar yerine bir yüzü düz, öbür yüzü yuvarlak dört çubuk ya da hayvan aşık kemikleri atılırdı. Pek çok araştırmacıya göre yukarı bakan düz yüz sayısı kadar ilerlenir, hiç yoksa beş sayılırdı.","Bu sayım, uzaktaki Kore’nin yut çubuklarınınkiyle tıpatıp aynıdır. Müzenin Şans odasında çubukları at ve bazı sayıların ne kadar daha sık geldiğini gör."],"cap":["Mısır atma çubukları (Şans odasında atabilirsin)"]},{"h":"Tutankamon’un oyun kutuları","p":["Howard Carter’ın 1922’de açtığı Tutankamon mezarında en az beş oyun kutusu vardı. En büyüğü abanoz ve fildişidendir; taşlar ve çubuklar için bir çekmecesi vardır.","O dönemde iki yüzü de oyun tahtası olan kutular yaygındı: bir yüzde senet, öbüründe Ur’un Kraliyet Oyunu’yla aynı yirmi haneli oyun. Kral öteki dünyada ikisini de oynayabilsin istenmişti."],"cap":["Tutankamon’un senet kutusu — Koleksiyon odasında 3D olarak görüp oynayabilirsin"]}],"tl":[["MÖ y. 3100","I. Hanedan mezarında senete benzer bir tahtanın parçaları"],["MÖ y. 2600","Eski Krallık mezar resimlerinde oyuncular"],["MÖ y. 1550’den","Yeni Krallık: senet öteki dünya yolculuğuyla bağlanır"],["MÖ y. 1323","Tutankamon’un mezarına beş oyun kutusu konur"],["MÖ y. 1250","Nefertari bir senet tahtasının başında resmedilir"],["1922","Carter Tutankamon’un mezarını açar"],["1978","Kendall kuralların yeniden kurulumunu yayımlar"]]},"lewis":{"title":"Kumdan çıkan satranç taşları","lead":"1831’de bir İskoç adasında bulunan Orta Çağ taşları — ve aynı atölyeden olup 188 yıl sonra bir çekmeceden çıkan bir taş.","s":["1831’de İskoçya’nın kuzeybatısındaki Lewis Adası’nda, çoğu mors dişinden oyulmuş bir taş hazinesi bulundu: 78 satranç taşı, masa oyunları için 14 pul ve bir toka; toplam 93 parça.","Tam olarak nerede ve nasıl bulundukları belli değil. En çok batı kıyısındaki Uig Koyu anılır ama başka yerler de öne sürülmüştür. Onları oraya kimin, neden gömdüğü bilinmiyor.","Taşların 12. yüzyılın sonlarında Norveç’in Trondheim çevresinde yapıldığı düşünülür: krallar, düşünceli kraliçeler, piskoposlar, tıknaz atlara binmiş şövalyeler ve kalkanının kenarını ısıran muhafızlar — muhtemelen İskandinav sagalarındaki berserkerler.","Bugün 82 taş British Museum’da, 11’i İskoçya Ulusal Müzesi’nde. Takımları tamamlamak için bazı taşların eksik olduğu uzun zamandır söylenir.","2019’da, Edinburghlı bir antikacının 1964’te yalnızca 5 sterline aldığı ve ailesinin çekmecede sakladığı bir muhafızın Lewis taşlarının atölyesine ait olduğu anlaşıldı. Sotheby’s’de 735.000 sterline satıldı."],"quiz":[["Taşlar Lewis’te hangi yıl bulundu?","1831","1066","1931","1700"],["Taşlar çoğunlukla neyden yapılmıştır?","Mors dişinden","Mermerden","Altından","Camdan"],["2019’da satılan muhafız hangi yıl 5 sterline alınmıştı?","1964","1831","1990","2018"]],"kf":["1831’de İskoçya’daki Lewis Adası’nda bulunan 93 taş ve disk","12. yüzyılın sonlarında Norveç’te, çoğu mors dişinden oyuldu","Bugün British Museum ile İskoçya Ulusal Müzeleri arasında paylaşılıyor"],"more":[{"h":"78 satranç taşı","p":["78 taş: 8 şah, 8 vezir/kraliçe, 16 piskopos, 15 şövalye, 12 muhafız ve 19 piyon — en az dört takımın parçaları.","Piskoposlar mitra takar. Satrançtaki “fil”in piskoposa dönüşmesi Avrupa’da oldu ve Lewis taşları bunun en erken örneklerindendir. Bazı muhafızlar kalkanlarını ısırır; bunların savaş öncesi kendinden geçen “berserk” savaşçılar olduğu düşünülür."],"cap":["Lewis satranç taşları (Koleksiyon odasında 3D olarak görebilirsin)","78 satranç taşının türleri"]},{"h":"Mors dişi ve kuzey denizleri","p":["Taşların çoğu mors dişinden, birkaçı balina dişindendir. Mors dişi, Grönland’dan ve kuzey Norveç’ten getirilen kuzey denizlerinin hazinesiydi.","Lewis o zaman Norveç kralının adalarındandı; 1266’daki Perth Antlaşması’yla İskoçya’ya geçti. Trondheim Katedrali yakınında aynı oymacılıkta parçalar bulunmuştur — taşların nerede yapıldığına dair bir ipucu."],"cap":[]},{"h":"Buluşun efsanesi ve bugünkü ünü","p":["Bulunuşu hakkında pek çok anlatı var: kumdan çıkaran bir inek ya da yerli Malcolm MacLeod. Bulan kişi onları hemen sattı ve Edinburgh üzerinden çoğunu British Museum satın aldı.","Somurtkan ve komik yüzleriyle bugün çok sevilirler, kopyaları dünyanın her yerinde satılır. Harry Potter ve Felsefe Taşı (2001) filmindeki büyücü satrancında Lewis taşlarından esinlenen taşlar kullanıldı."],"cap":[]}],"tl":[["12. yy sonu","Taşlar Norveç’te (Trondheim çevresi) yapılır"],["1266","Perth Antlaşması, Lewis’in de olduğu adaları İskoçya’ya verir"],["1831","93 parça Lewis’te birlikte bulunur"],["1831–32","British Museum 82 tanesini alır"],["1888","İskoç ulusal müzesi 11 tanesini edinir"],["2001","Harry Potter’ın büyücü satrancında görünürler"],["2019","5 sterline alınmış bir muhafız 735.000 sterline satılır"]]},"tafl":{"title":"Kralın kaçışı ve hatalı bir çeviri","lead":"Vikinglerin tahta oyununun kuralları, 18. yüzyıldan bir Laponya seyahat günlüğünden çıkarıldı.","s":["Viking çağında Kuzey Avrupa’da tafl adlı tahta oyunları oynanırdı. Ortadaki kral ve az sayıdaki savunucusu, onları kuşatan daha büyük bir orduya karşı savaşır: iki eşit olmayan tarafın oyunu.","1932’de İrlanda’nın Ballinderry kentinde bulunan 10. yüzyıldan ahşap bir tahtada 7×7 delik vardır; ortası ve dört köşesi işaretlidir — muhtemelen kralın yeri ve sığınakları.","Ama kuralları anlatan Orta Çağ kaydı neredeyse hiç kalmadı. Önemli bir ipucu, 25 yaşındaki doğa bilimci Linnaeus’un 1732’deki Laponya (kuzey İsveç) yolculuğunun günlüğüdür. Orada Samilerin oynadığı tablut adlı oyunun nasıl oynandığını not etti.","Günlük 1811’de İngilizce çevirisiyle yayımlandı ama çeviride hatalar vardı. Ona dayanan Murray’nin yeniden kurgusu (1913) uzun yıllar tafl’ın standart kuralı oldu.","Sonradan oyuncular ve araştırmacılar hatayı düzeltti; bugün kuralların birçok sürümü oynanıyor. Atlas’taki tafl da bunlardan biri."],"quiz":[["Linnaeus Laponya’da hangi oyunu not etti?","Tablut","Senet","Mangala","Satranç"],["Savunucular hangi taşı bir köşeye götürmeye çalışır?","Kralı","Kraliçeyi","Bir bayrağı","Bir gemiyi"],["Hatalı İngilizce çeviri hangi yıl yayımlandı?","1811","1732","1932","1066"]],"kf":["Ortadaki kral ve birkaç savunucu, daha kalabalık bir orduyla çevrilidir: eşit olmayan iki tarafın oyunu","Viking çağında Kuzey Avrupa’da oynanırdı; tahtalar 7×7’den 19×19’a kadar çeşitliydi","Kurallar bize Linnaeus’un 1732 tarihli gezi günlüğü ve onun hatalı İngilizce çevirisi yoluyla ulaştı"],"more":[{"h":"Ballinderry tahtası","p":["İrlanda’nın ortasındaki bir göl yerleşiminden (crannog) çıkan Ballinderry tahtası porsuk ağacından yapılmıştır. 7×7 düzendeki 49 deliğe, altında çivisi olan taşlar takılarak oynandığı düşünülür.","Çerçeveden insan başı biçiminde oyulmuş bir sap çıkar: yanınızda taşıyabileceğiniz bir tahtaydı. İrlanda kaynakları brandubh (“kara kuzgun”) adlı 7×7’lik bir tafl’dan söz eder; belki de bu tahtada oynanıyordu."],"cap":["Ballinderry tahtası (7×7) üzerinde İrlanda oyunu brandubh’un başlangıç dizilişi. Altın halkalar ortayı ve dört köşeyi gösterir"]},{"h":"Linnaeus’un tablut’u","p":["Linnaeus’un kaydettiği tablut 9×9’luk bir tahtada oynanır. Kral ortadaki tahtta durur; 8 “İsveçli”si 16 “Moskovalı”ya karşı savaşır.","Bütün taşlar kale gibi düz bir çizgide istediği kadar ilerler ve iki düşman arasında sıkıştırılınca alınır. Kral kenara ulaşırsa savunanlar, kralı dört yandan kuşatırlarsa saldıranlar kazanır. Linnaeus Latince ile İsveççeyi karıştırarak yazmıştı; İngilizce çeviride birkaç nokta değişti."],"cap":["Linnaeus’un kaydettiği tablut (9×9): ortadaki tahtta kral, 8 savunucu, 16 saldırgan. Kral yeşil kenar karelerinden birine ulaşırsa savunan taraf kazanır"]},{"h":"Büyüyen tahtalar, kaybolan bir oyun","p":["7×7’nin yanında 9×9, Galler’in 11×11’i ve hatta 19×19’luk tahtalar vardı. En büyüğü Alea Evangelii, 12. yüzyıldan bir el yazmasında çizilmiştir; el yazması oyunun 10. yüzyılda İngiltere Kralı Æthelstan’ın sarayından geldiğini söyler.","Satranç 12. ve 13. yüzyıllarda Kuzey Avrupa’ya yayılınca tafl yavaş yavaş unutuldu. Tablut yalnızca uzak Laponya’da yaşadı ve Linnaeus onu tesadüfen kaydetti. Bugün 11×11 tahtalarda uluslararası turnuvalar düzenleniyor ve oyun yeni oyuncular kazanıyor."],"cap":["Lewis buluntusu (12. yüzyıl): satranç taşlarının yanında bir tahta oyununa ait 14 disk bulundu"]}],"tl":[["10. yy","Ballinderry tahtası İrlanda’da yapılır"],["924–939","Æthelstan’ın sarayında Alea Evangelii oynandığı anlatılır"],["12. yy","Alea Evangelii bir el yazmasına çizilir"],["12.–13. yy","Satranç Kuzey Avrupa’ya yayılır, tafl kaybolur"],["1732","Linnaeus Laponya’da tablut’u kaydeder"],["1811","Günlüğün İngilizce çevirisi Lachesis Lapponica yayımlanır"],["1913","Murray, A History of Chess’te tafl’ı yeniden kurar"],["1932","Ballinderry tahtası bulunur"]]},"goose":{"title":"Bir krala hediye edilen kaz oyunu","lead":"63 karelik bir sarmalda zarla yapılan yarış bir krala hediye edildi, sonra bütün Avrupa’da oynandı.","s":["Kaz oyunu bir yarış oyunudur: zar atılır ve 63 karelik bir sarmalda ortadaki hedefe doğru ilerlenir. Kaz resmi olan bir kareye gelen, aynı sayı kadar yeniden ilerler. Kuyu, zindan ve ölüm kareleri sizi durdurur ya da başa gönderir.","Oyunun 16. yüzyıl İtalya’sında doğduğu düşünülür. Toskana Büyük Dükü I. Francesco de’ Medici’nin oyunu 1574–1587 arasında İspanya Kralı II. Felipe’ye hediye ettiği anlatılır.","İngiltere’de Londralı matbaacı John Wolfe 1597’de “yeni ve pek hoş kaz oyunu”nu kayda geçirdi. 17. ve 18. yüzyıllarda oyun bütün Avrupa’da çok sevildi.","Kâğıda basılarak yayıldı ve yeni resimlerle sayısız sürümü yapıldı: coğrafya öğreten tahtalar, masal ve fabl tahtaları, hatta reklam tahtaları. Sonraki birçok yarış oyununa örnek olduğu düşünülür.","Metropolitan Sanat Müzesi’ndeki iki yüzlü bir tahtanın bir yüzünde kaz oyunu, öbür yüzünde satranç vardır. 16. yüzyılın sonlarında Hindistan’ın Gucerat bölgesindeki zanaatkârlarca yapıldığı düşünülür ve günümüze ulaşan en eski kaz oyunu tahtası olabilir."],"quiz":[["Kaz oyununda kaç kare vardır?","63","64","100","30"],["Oyunu İspanya Kralı’na kimin hediye ettiği anlatılır?","I. Francesco de’ Medici","Napolyon","I. Elizabeth","XIV. Louis"],["Kaz karesine gelince ne olur?","Aynı sayı kadar yeniden ilerlersin","Başa dönersin","Bir tur beklersin","Bir rakiple yer değiştirirsin"]],"kf":["Zarla, 63 karelik bir sarmal boyunca ortadaki hedefe koşulan bir yarış oyunu","16. yüzyıl İtalya’sında doğdu; Medicilerin İspanya kralına hediye ettiği anlatılır","Basılı kâğıtlarla yayıldı; yeni resim ve konularla sayısız sürümü yapıldı"],"more":[{"h":"63 karelik sarmal","p":["En bilinen sürümde kazların yanında birkaç özel kare vardır. 6’daki köprü sizi 12’ye taşır; 19’daki handa bir tur beklersiniz; 31’deki kuyuda ve 52’deki zindanda başka bir oyuncu gelip kurtarana kadar kalırsınız.","42’deki labirent 30’a, 58’deki ölüm başlangıca geri gönderir. 63’e tam zarla gelmek gerekir; fazlası kadar geri dönülür. En zor adım son adımdır."],"cap":["63 karenin dıştan içe sarmal dizilişi. Yeşil: kazlar; mavi: köprü; sarı: bekletenler (han, kuyu, zindan); kırmızı: geri gönderenler (labirent, ölüm); altın: hedef"]},{"h":"Dokuzun bilmecesi","p":["Kazlar 5, 9, 14, 18… karelerindedir; aralıklar 4 ve 5 olarak değişir. 9’un her katında kaz bulunduğundan, 9’a gelen bir 9 sizi 18’e, 27’ye… ve dosdoğru 63’e taşırdı.","Bu yüzden iki zarla oynanan sürümlerde özel bir kural vardır: ilk atış 6 ve 3 ise 26’ya, 5 ve 4 ise 53’e gidilir. 63 sayısı 7×9’dur ve o dönemde ömrün en tehlikeli yılı sayılan 63 yaşla ilişkilendirilmiştir."],"cap":["Kazlar sırayla 4 ve 5 kare arayla durur, bu yüzden 9’un her katında bir kaz vardır. İlk atışta gelen 9, kazdan kaza zıplayarak doğrudan 63’e götürürdü"]},{"h":"Matbaayla yayılış","p":["Oyun tahtaları bakır levhalardan ve tahta kalıplardan basıldı ve ucuzladı. Fransa’da jeu de l’oie, İspanya’da juego de la oca denildi; İspanya’da “kazdan kaza” diye başlayan bir tekerleme hâlâ deyim olarak kullanılır.","Yeni resimli sürümler ardı ardına çıktı: coğrafya ve tarih öğreten tahtalar, Fransız Devrimi’ni ya da Napolyon’u anlatanlar, hatta ürün reklamları. Aynı 63 karelik yolun üzerine her çağ kendi dertlerini çizdi."],"cap":[]}],"tl":[["16. yy","İtalya’da doğduğu düşünülür"],["1574–87","I. Francesco de’ Medici’nin İspanya Kralı II. Felipe’ye hediye ettiği anlatılır"],["16. yy sonu","Hindistan’ın Gucerat bölgesinde bir yüzü kaz oyunu, öbür yüzü satranç olan çift yüzlü tahta yapılır"],["1597","John Wolfe oyunu Londra’da basım için kaydettirir"],["17.–18. yy","Avrupa’da büyük moda; konulu sürümler çoğalır"],["1790’lar","Fransız Devrimi konulu tahtalar yapılır"],["19. yy","Birçok ülkede çocuk oyunu olarak toplu basılır"]]},"shogi":{"title":"Shogi’de alınan taşları geri koyma kuralı ne zaman doğdu?","lead":"Bütün satranç ailesinde yalnızca shogi, alınan taşları kendi taşın olarak tahtaya geri koymana izin verir. Bu kural ne zaman ve neden ortaya çıktı?","s":["Satrancın Hint atası doğuya ve batıya yayıldı; Japonya’da shogi oldu. Japonya’nın en eski shogi taşları, 1990’ların başında Nara’daki Kōfuku-ji’nin eski alanında yapılan kazıda çıkan 16 taştır. Yanlarında 1058 (Tenki 6) tarihli bir etiket bulunduğu için taşların da aynı döneme ait olduğu düşünülür.","Dönemin yazıları da shogi’den söz eder. 11. yüzyıl ortasından Shin Sarugaku-ki oyunun adını anar; Heian döneminin sonundaki kayıtları toplayan Nichūreki ise krallar, altın ve gümüş generaller, atlar, mızraklar ve piyonlarla oynanan “Heian shogi”sini anlatır.","Kamakura ve Muromachi dönemlerinde daha çok taşlı büyük biçimler doğdu. Bugünkü oyunun atası olan “küçük shogi” kale ve fili ekledi — bir de artık olmayan bir taşı: sarhoş fili.","Taşları geri koyma kuralının 16. yüzyıl dolaylarında doğduğu düşünülür. Rivayete göre İmparator Go-Nara sarhoş fili küçük shogi’den çıkarttı; kuralın da o sıralarda başladığı sanılır.","Nedeni belli değil. Bir açıklama: iki tarafın taşları aynı renktedir ve yalnızca yönleriyle ayrılır; bu yüzden alınan bir taş kolayca yeniden kullanılır. Bu kural sayesinde tahta boşalmaz ve beraberlik nadirdir."],"quiz":[["Kōfuku-ji taşlarıyla bulunan etikette hangi tarih yazıyordu?","1058 (Tenki 6)","701 (Taihō 1)","1582 (Tenshō 10)","1868 (Meiji 1)"],["Geri koyma kuralının ne zaman doğduğu düşünülür?","16. yüzyıl dolaylarında","8. yüzyıl dolaylarında","19. yüzyıl dolaylarında","20. yüzyılda"],["Alınan taşların kolay kullanılmasının nedeni olarak ne gösterilir?","İki tarafın taşları aynı renkte, yönle ayrılır","Taşlar altındandı","Tahtada az kare vardı","Taşlar zarla seçilirdi"]],"kf":["Hindistan’da doğup Japonya’da gelişen bir satranç akrabası; 9×9 tahtada oynanır","En eski taşlar, 1058 tarihli bir etiketle birlikte Kōfuku-ji’nin eski alanında bulundu","Alınan taşları kendi taşı gibi sürmek, yani “eldeki taşlar”, muhtemelen 16. yüzyıl civarında doğdu"],"more":[{"h":"Tek renk, yönle ayırt etme","p":["Satranç taşları beyaz ve siyaha boyanır, ama shogi taşlarının hepsi ahşap rengindedir: taşın kime ait olduğu, beşgen taşın sivri ucunun hangi yöne baktığından anlaşılır. Alınan bir taşı çevirip yeniden tahtaya sürmeyi mümkün kılan da bu biçimdir.","Her taşın üzerinde adı yazılıdır ve rakip bölgeye girince ters çevrilip “terfi” edebilir. Piyon arka yüzündeki と olur ve altın general gibi hareket eder. Oyma figürler yerine yazılı yassı taşlar kullanmak, shogi’nin Doğu Asya’daki akrabaları Çin xiangqi’si ve Kore janggi’siyle ortak özelliğidir."],"cap":["Shogi taşları iki taraf için de aynı renktedir; sivri ucun yönüyle ayırt edilir. Sağda: ters çevrilip “terfi etmiş” piyon (tokin)"]},{"h":"Dev shogilerin çağı","p":["Kamakura ve Muromachi dönemlerinden Edo dönemine kadar, taş türleri ve sayısı giderek artan büyük shogiler yapıldı. 12×12’lik chū shogi Edo dönemi boyunca çok oynandı ve bugün de meraklıları var.","Kayıtlar daha da ileri gider: 15×15 dai shogi, 25×25 tai shogi ve 36×36 tahtada 804 taşlı taikyoku shogi. Ama gündelik oyun 9×9’luk shō shogi idi; eldeki taşları kazanarak bugünkü shogi oldu."],"cap":["Tahta boyutlarının karşılaştırması (tek köşeden çizildi): 9×9 bugünkü shogi (40 taş), 12×12 chū shogi (92), 15×15 dai shogi (130), 25×25 tai shogi (354), 36×36 taikyoku shogi (804)"]},{"h":"Edo’da shogi","p":["Edo döneminde şogunluktan maaş alan shogi aileleri ortaya çıktı; Ōhashi Sōkei ilk usta sayılır. Her yıl en iyiler şogunun önünde “kale oyunları”nda karşılaştı; bunlar sonradan 17 Kasım’a sabitlendi — bugünkü Shogi Günü buradan gelir.","Shogi halkın da eğlencesiydi: Harunobu’nun baskısında cibinliğin yanında oynayan genç bir çift görülür. Itō Kanju’nun Shōgi Zukō’su (1755) gibi sanat eseri değerinde tsume-shogi problem kitapları da çıktı."],"cap":["Suzuki Harunobu’nun renkli baskısı (y. 1767–69): cibinliğin yanında shogi oynayan genç bir kadın ve erkek"]}],"tl":[["1058","Kōfuku-ji’nin eski alanından taşlar (Tengi 6 yılı etiketiyle bulundu)"],["11. yy ortası","Shinsarugakuki shogi’den söz eder"],["Kamakura başı","Nichūreki, Heian shogisinin taşlarını sayar"],["y. 16. yy","Eldeki taşlar kuralının doğduğu düşünülür"],["1612","Ōhashi Sōkei ve diğerlerinin şogunluktan maaş aldığı anlatılır"],["1716","Kale oyunları 17 Kasım’a sabitlenir"],["1755","Itō Kanju’nun Shōgi Zukō’su"],["1975","17 Kasım Shogi Günü olur"]]},"pachisi":{"title":"Paçisi nasıl ludo oldu","lead":"Hint saraylarında oynanan haç biçimli bir tahta oyunu adını değiştirdi ve dünyanın dört bir yanındaki çocuk odalarına ulaştı.","s":["Hindistan’da çaupar ve paçisi oyunları vardır: dört oyuncu taşlarını haç biçimli bir tahtanın çevresinde ilerletir. Çauparda uzun zarlar (pasa), paçiside atılan kauri kabukları kullanılır. Paçisi adı “yirmi beş” demektir; kabuklarla atılabilen en yüksek sayıdır.","Tanrılar bile oynardı. 17. yüzyıl sonundan bir resimde tanrı Şiva ve eşi Parvati, bir kaplan postu üzerinde çaupar tahtasının başında oturur.","Babür imparatoru Ekber’in (16. yüzyıl) şehri Fatehpur Sikri’de bir avlunun zemininde hâlâ dev bir haç biçimli tahta durur. Ekber’in renkli giysili insanları taş olarak kullanıp oynadığı anlatılır.","19. yüzyılda oyun denizleri aştı. ABD’de “Parcheesi” adıyla satıldı ve 1874’te marka olarak tescil edildi. Britanya’da 1890’larda “Ludo” (Latince “oynuyorum”) adıyla satışa çıktı ve bir aile klasiği oldu.","Ludo daha basittir: tek zar vardır ve taş 6 gelince çıkar. Dünyanın her yerinde başka adlarla akrabaları vardır; İspanya’da parchís, Almanya’da Mensch ärgere Dich nicht (“Kızma birader”) gibi."],"quiz":[["“Paçisi” adı ne demektir?","Yirmi beş","Kralın yolu","Haç","Kauri kabuğu"],["Ekber’in hangi şehrinde dev tahtalı avlu hâlâ durur?","Fatehpur Sikri","Delhi’deki Kutub Minar","Tac Mahal","Ellora"],["“Ludo” Latincede ne demektir?","Oynuyorum","Kazanıyorum","Koşuyorum","Atıyorum"]],"kf":["Haç biçimli bir Hint tahtasında, iki takım hâlinde dört oyuncunun taşlarını bir tur dolaştırdığı yarış oyunu","Adı “25” demektir: deniz kabuklarıyla gelen en büyük sayı","19. yüzyılda denizleri aşıp Parcheesi, Ludo ve başka adlarla dünyaya yayıldı"],"more":[{"h":"Haç ve yol","p":["Paçisi tahtası, ortadaki çarkoniden dört kolun uzandığı bir haçtır. Her kol 3 × 8 karedir, toplam 96 kare. Tahtalar çoğu zaman kumaşa işlenirdi; böylece katlanıp kaldırılabilirdi.","Taşlar merkezden çıkar, kendi kolunun orta sütunundan aşağı iner, tahtayı saat yönünün tersine bir kez dolaşır ve orta sütundan merkeze döner. Karşılıklı oturanlar ortaktır; ikisi de dört taşını eve getirince takım kazanır."],"cap":["Haç biçimli tahta (her kol 3 × 8 kare). Mavi çizgi bir oyuncunun yolu: kendi kolunun ortasından aşağı iner, saat yönünün tersine tam tur atar ve ortadan merkeze geri çıkar"]},{"h":"Kabukları saymak","p":["Paçisi’de altı kauri kabuğu atılır; ağzı yukarı düşenlerin sayısı hamleyi belirler. İkiden altıya kadar o kadar gidilir; ama yalnız biri yukarıdaysa 10, hiçbiri değilse 25 kare gidilir.","64’te 1 olasılıkla 25 en nadir ve en büyük atıştır ve oyuna adını vermiştir. 6, 10 ya da 25 gelirse bir kez daha atılır. Çaupar ise üzerinde 1, 2, 5 ve 6 yazan üç uzun çubuk zarla oynanır."],"cap":["Altı kauri kabuğundan kaçının ağzı yukarı düştüğü (üst sıra) ve kaç kare gidildiği (alt sıra). Çubuk yüksekliği, her kabuk iki yüze eşit olasılıkla düşerse ne sıklıkta geldiğini gösterir"]},{"h":"Yeni adlar, yeni ülkeler","p":["Hindistan’daki İngilizler aracılığıyla oyun 19. yüzyılda Avrupa’ya ve Amerika’ya ulaştı. ABD’de Parcheesi markası oldu; Britanya’da Ludo 1896’da patent aldı, kurallar sadeleşti ve kabukların yerini tek bir küp zar aldı.","Almanya’da 1914’te “Mensch ärgere dich nicht” (“Kızma”) çıktı, İspanya’da parchís oynanır. Adlar ve ayrıntılar ülkeden ülkeye değişse de iskelet aynıdır: haçın çevresini dolaşıp eve dönmek."],"cap":[]}],"tl":[["16. yy","Ekber’in Fatehpur Sikri’sinde dev bir haç tahtalı avlu yapılır"],["17.–18. yy","Hint minyatürlerinde çaupar başında toplanmış insanlar sıkça çizilir"],["1694–95","Devidasa, çaupar oynayan Şiva ve Parvati’yi resmeder"],["1874","Parcheesi ABD’de marka olur"],["1896","Ludo Britanya’da patent alır"],["1914","“Mensch ärgere dich nicht” Almanya’da satışa çıkar"]]},"go":{"title":"1300 yıllık bir go tahtasının anlattıkları","lead":"Shōsōin’deki go tahtasında bugünkü gibi 19 çizgi var — ve bugünkünden farklı olarak 17 çiçek işareti.","s":["Go eski Çin’de doğdu. Efsaneye göre bilge kral Yao onu oğlunu eğitmek için yarattı. Milattan önce yazılmış Mencius kitabı, oyunun ustası Yi Qiu’nun adını anar.","Tahtanın büyüklüğünün zamanla değiştiği düşünülür: eski dönemlerde 17 çizgili tahtalar da kullanıldı, sonra bugünkü 19 çizgili tahta yaygınlaştı.","Go’nun Japonya’ya ne zaman geldiği belli değil ama Nara döneminde oynanıyordu. Keşişler ve rahibeler için kurallar müziği ve kumarı yasaklarken go ve koto’ya izin veriyordu — sugoroku’dan çok farklı bir tutum.","Shōsōin’deki kakmalı go tahtası, İmparator Shōmu’yla bağlantılı bir hazine olarak günümüze ulaştı. Bugünkü gibi 19 çizgisi var ama bugünkü tahtanın 9 yıldız noktası olan yerlerde 17 çiçek işareti var. İki çekmecesi birbirine bağlıdır: birini çekince öteki de çıkar. Shōsōin’de ayrıca kırmızı ve lacivert boyanmış, kuş desenleri oyulmuş fildişi go taşları da saklanır.","Heian döneminde Genji’nin Hikâyesi go oynayanları anlatır. Edo döneminde Hon’inbō gibi evler şogunluğa hizmet etti ve go, profesyonel oyuncuların ustalık yarıştırdığı bir sanata dönüştü."],"quiz":[["Shōsōin go tahtasında kaç çizgi var?","19","17","13","9"],["Kurallar keşişlere ve rahibelere neye izin veriyordu?","Go ve koto","Sugoroku","Kumar","Kemari"],["Shōsōin tahtasında yıldız noktaları yerine kaç çiçek işareti var?","17","9","4","25"]],"kf":["Siyah ve beyaz taşlar çizgilerin kesiştiği noktalara konur; daha geniş alanı çevirmek için yarışılır — eski Çin’de doğmuş bir oyun","17 çizgili tahtalar devrinin ardından 19 çizgiye geçildi; Shōsōin’de 8. yüzyıldan 19 çizgili bir tahta durur","Edo Japonya’sında go aileleri şogunluğa hizmet etti; 21. yüzyılda bir yapay zekâ dünyanın en iyi oyuncusunu yendi"],"more":[{"h":"Kuşat, al, alanı genişlet","p":["Go’da siyah ve beyaz sırayla, çizgilerin kesiştiği noktalara taş koyar. Konan taş bir daha oynamaz. Bir taşın (ya da grubun) yanındaki bütün boş noktalar rakip taşlarla dolarsa, taş alınır ve tahtadan kaldırılır.","Sonunda çevrilen alan ile alınan taşların toplamı fazla olan kazanır. Kurallar azdır ama tahta geniştir: 19 çizgili bir tahtada olabilecek konumların sayısı yaklaşık 10 üzeri 170 olarak hesaplanmıştır."],"cap":["Taş alma. Solda: siyah taşın yanında dört boş nokta (kırmızı) var. Ortada: beyaz onu üç yandan kuşatmış, bir nokta kalmış. Sağda: sonuncusu da kapanır ve siyah taş alınır"]},{"h":"17 çizgiden 19’a","p":["Çin’in Hebei eyaletindeki Wangdu’da, Doğu Han dönemine ait bir mezardan 17 çizgili taş bir go tahtası çıktı. Yaklaşık 6. yüzyıla tarihlenen Dunhuang Go Klasiği ise 361 noktadan, yani 19 çizgili tahtadan söz eder. Tahta bu arada büyümüş görünüyor.","Shōsōin tahtası 19 çizgilidir, ama bugünkü dokuz yıldız noktası yerine 17 yerde çiçek işaretleri taşır. 289 noktadan 361’e geçiş, oyunu çok daha derin yaptı."],"cap":["17 ve 19 çizgili tahtaların kesişim noktası sayısıyla karşılaştırması. Bugünkü tahtadaki dokuz siyah nokta “yıldız noktaları”dır"]},{"h":"Ölümsüzlerin go’su, ustaların go’su","p":["Bir Çin masalı, dağda ölümsüzlerin go oynayışını seyreden bir oduncunun, kendine geldiğinde baltasının sapı çürüyecek kadar yıl geçtiğini fark ettiğini anlatır. Ölümsüzlerin eğlencesi olarak go, tabaklarda ve resimlerde sevilen bir konuydu.","Edo Japonya’sında Hon’inbō gibi go aileleri şogunluktan maaş aldı ve go bir sanat olarak inceltildi. Hon’inbō Shūsai’nin 1938’deki veda oyunu, Kawabata Yasunari’nin “Go Ustası” romanına dönüştü. 2016’da yapay zekâ AlphaGo, dünyanın en iyi oyuncusu Lee Sedol’ü 4–1 yenerek dünyayı şaşırttı."],"cap":["Go oynayan ölümsüzlerin oyulduğu lake tabak (Ming hanedanı, Xuande dönemi, 1425–36)"]}],"tl":[["y. MÖ 4. yy","Mencius go ustası Yi Qiu’nun adını anar"],["Doğu Han","Wangdu’daki bir mezara 17 çizgili taş tahta konur"],["y. 6. yy","Dunhuang Go Klasiği 19 çizgi ve 361 noktayı anlatır"],["8. yy","Shōsōin’in kakmalı sandal ağacı go tahtası"],["1612","Hon’inbō Sansa ve diğerlerinin şogunluktan maaş aldığı anlatılır"],["1938","Hon’inbō Shūsai’nin veda oyunu; sonra Kawabata’nın romanı"],["2016","AlphaGo, Lee Sedol’ü 4–1 yener"]]},"draughts":{"title":"Dama nasıl doğdu","lead":"Bir Arap tahta oyunu, satranç tahtası ve satrancın veziri: damanın bu üçünün buluşmasından doğduğu düşünülür.","s":["Damanın atası olarak çizgilerle birleştirilmiş 5×5 noktalık bir ızgarada oynanan alkerk görülür. Arapçada kırk diye anılırdı ve 10. yüzyıldan Şarkılar Kitabı’nda adı geçer. Mağribîler onu İspanya’ya getirdi; kuralları Kastilya Kralı X. Alfonso’nun 13. yüzyılda hazırlattığı Oyunlar Kitabı’nda yer alır.","12. yüzyıl dolaylarında, muhtemelen güney Fransa’da, alkerk taşları satranç tahtasında oynatılmaya başlandı. Böylece “fierges” doğdu. Taşlar, o dönemin satranç veziri “fers” ile aynı adı aldı.","Karşı kenara ulaşan taşın güçlenmesi, yani terfi, 13. yüzyıl ortasından bir kronikte bile anılır. Belki vezire dönüşen satranç piyonundan alınmıştır.","Büyük değişim 1535 dolaylarında Fransa’da geldi: zorunlu alma eklendi — alabiliyorsan almak zorundasın — ve oyuna “jeu forcé”, “zorunlu oyun” dendi. İngiliz draughts’ı ve Amerikan checkers’ı bundan gelir.","Zorunlu alma olmayan eski oyun “hanımlar için yumuşak oyun” olarak yaşadı ve sonra 10×10 tahtalı uluslararası damaya yol açtı. Tek bir atadan birçok “vezir oyunu” dallandı."],"quiz":[["Damanın atası sayılan oyun hangisidir?","Alkerk","Senet","Liubo","Mangala"],["Zorunlu alma ne zaman ve nerede eklendi?","1535 dolaylarında Fransa’da","10. yüzyılda Bağdat’ta","1900’de Amerika’da","8. yüzyılda Japonya’da"],["Fierges taşları neyin adını aldı?","Satranç vezirinin (fers)","Satranç şahının","Zarların","Atın"]],"kf":["Arap oyunu alkerkin taşları satranç tahtasına taşınınca doğdu","Taşlar çapraz ilerler ve atlayarak alır; son sıraya varınca dama olur","1535 dolaylarında zorunlu alma eklendi; 2007’de oyun (8 × 8) çözüldü"],"more":[{"h":"Nokta ve çizgilerden satranç tahtasına","p":["Alkerk tahtası, 5 × 5 ızgarada çizgilerle birleştirilmiş 25 noktadır. Her taraf 12 taş dizer ve oyun ortadaki tek boş noktadan başlar. Taşlar çizgiler boyunca ilerler ve yanındaki rakip taşın üzerinden atlayarak onu alır.","Taşlar satranç tahtasına geçince yalnız bir renkteki kareler kullanılır oldu. 8 × 8 tahtada 32 koyu kare vardır; her iki yanda ilk üç sıra doldurulunca taraf başına 12 taş eder — alkerkle aynı sayı."],"cap":["Alkerk tahtası ve başlangıç dizilişi: düz ve çapraz çizgilerle birleşen 5 × 5 nokta, her yanda 12 taş, yalnız orta boş"]},{"h":"Atla, al, dama ol","p":["Taşlar çaprazına bir kare ilerler; yanındaki rakip taşın arkası boşsa onun üzerinden atlayarak alır. Ardından başka bir alma mümkünse atlamaya devam eder. Bugünkü kurala göre alabiliyorsan almak zorundasın.","Son sıraya varan taşın üstüne ikinci bir taş konur ve dama olur; artık geri de gidebilir. 10 × 10 tahtadaki uluslararası oyunda dama çapraz boyunca istediği kadar uzağa gider ve bu, oyun sonunu tümüyle değiştirir."],"cap":["Alma ve dama olma. Kırmızı taş iki beyaz taşı art arda atlayarak alır (×), sonra son sıraya varıp üst üste iki taştan oluşan dama olur"]},{"h":"Çözülmüş bir oyun, büyüyen bir aile","p":["Kanada’da Jonathan Schaeffer ve ekibi Chinook adlı programı yaptı. Program 1992’de, 40 yılı aşkın sürede neredeyse hiç yenilmemiş usta Marion Tinsley ile oynadı ve Tinsley kazandı. Ekip hesaplamayı sürdürdü ve 2007’de, iki taraf da kusursuz oynarsa oyunun (8 × 8) berabere bittiğini kanıtladı.","Bu arada aynı atadan gelen aile dünyanın her yerinde yaşıyor: 10 × 10 uluslararası dama, Rus şaşkisi, düz hareket eden Türk daması, 12 × 12 Kanada daması… ve her ülkede turnuvalar sürüyor."],"cap":[]}],"tl":[["10. yy","Şarkılar Kitabı’nda kırk (alkerk) adı geçer"],["y. 12. yy","Fierges muhtemelen güney Fransa’da doğar"],["1283","X. Alfonso’nun Oyunlar Kitabı alkerki anlatır"],["y. 1535","Fransa’da zorunlu alma eklenir"],["1547","Torquemada İspanya’da dama üzerine ilk kitabı yayımlar"],["18. yy","10 × 10 tahta Fransa’da ve Hollanda’da yayılır"],["1992","Tinsley, Chinook programını yener"],["2007","Oyunun (8 × 8) kusursuz oyunla berabere olduğu kanıtlanır"]]},"reversi":{"title":"Reversi ve Othello: kim icat etti?","lead":"Siyah ve beyaz taşları sıkıştırıp çevirdiğin bir oyun — ve 19. yüzyıl İngiltere’sinde onu sahiplenmek için çekişen iki adam.","s":["1880’lerin Londra’sında iki İngiliz, Lewis Waterman ve John W. Mollett, her biri oyunun mucidi olduğunu söyledi ve ötekini sahtekârlıkla suçladı.","Mollett’in oyunu “Annexation” (İlhak) haç biçimli bir tahtada oynanırdı. Waterman’ın “Reversi”si ise sıradan 8×8 tahtayı kullanıyordu ve günümüze ulaşan onun biçimidir. Ad üzerindeki kavga mahkemeye bile taşındı.","Reversi Avrupa’ya yayıldı; 1893’te Alman Ravensburger firması onu ilk ürünlerinden biri olarak çıkardı. Japonya’da Meiji dönemi kitaplarında anlatıldı ve “genpei-go” diye de anıldı.","Ama ilgi uzun sürmedi. 1971’de Goro Hasegawa, ilk dört taşı ortada çapraz dizerek açılışı sabitleyen “Othello”yu piyasaya sürdü ve oyun Japonya’da çılgınlık hâline geldi.","Adın Shakespeare’in oyunundan geldiği söylenir: siyahi komutan Othello ile beyaz tenli eşi Desdemona, siyah ve beyaz taşları çağrıştırır. Bugünkü turnuva kuralları Othello’nunkilerdir."],"quiz":[["Reversi için çekişen iki adam ne zaman ve nerede yaşadı?","19. yüzyıl İngiltere’si","18. yüzyıl Fransa’sı","20. yüzyıl Japonya’sı","16. yüzyıl İtalya’sı"],["Mollett’in Annexation tahtası ne biçimdeydi?","Haç","Daire","Üçgen","8×8 kare"],["Othello’yu 1971’de kim piyasaya sürdü?","Goro Hasegawa","Hon’inbō Shūsaku","Lewis Waterman","Ravensburger"]],"kf":["Rakibin taşlarını kendi taşlarınla kıstırıp çevirirsin; sonunda taşı çok olan kazanır","1880’lerin Londra’sında iki İngiliz, mucitlik için çekişti","1970’lerde Japonya’da Othello adıyla çılgınlığa dönüştü; 2023’te kusursuz oyunda beraberlik olduğu gösterildi"],"more":[{"h":"Kıstır ve çevir","p":["Taş yalnızca, rakibin bir sıra taşını kendisiyle kendi taşlarından biri arasında kıstıracağı yere konabilir. Sıralar sekiz yönde uzanır — yatay, dikey ve çapraz — ve tek hamle birkaçını birden kıstırabilir. Kıstırılan bütün taşlar senin rengine çevrilir.","Hamlen yoksa pas geçersin; iki oyuncu da oynayamayınca oyun biter. Köşe taşları asla kıstırılamaz, bu yüzden köşe almak büyük üstünlüktür. Güçlü oyuncular o anki taş sayısından çok, rakibin oynayabileceği yerleri azaltmaya bakar."],"cap":["Taşların çevrilişi. Kırmızı halkalı kareye konan siyah taş, beyazları yatay, dikey ve çapraz üç yönde kıstırır; altın kenarlı yedi taşın hepsi siyaha döner"]},{"h":"İlk dört taş","p":["Eski reversi’de iki oyuncu ilk dört taşı sırayla ortadaki dört kareye koyardı; bu yüzden açılış yan yana da, çapraz da olabilirdi.","Othello çapraz başlangıcı sabitledi. İlk hamleden itibaren iki renk de kolayca kıstırılabildiği için mücadele hemen başlar. Bugünkü dünya şampiyonaları bu konumdan başlar."],"cap":["İlk dört taş. Solda: eski reversinin olası bir başlangıcı (aynı renkler yan yana). Sağda: Othello’nun sabitlediği çapraz başlangıç"]},{"h":"İnsanlar ve bilgisayarlar","p":["Othello Japonya’dan dünyaya yayıldı; ilk Dünya Othello Şampiyonası 1977’de Tokyo’da yapıldı. Kurallar basit olduğu için farkı hesap derinliği yaratır; güçlü oyuncular onlarca hamle ilerisini görür.","1997’de Logistello programı dünya şampiyonu Takeshi Murakami ile altı oyun oynadı ve hepsini kazandı. 2023’te hesaplar, 8 × 8 Othello’nun iki taraf da kusursuz oynarsa berabere bittiğini gösterdi."],"cap":[]}],"tl":[["1880’ler","Waterman ve Mollett Londra’da mucitlik için çekişir"],["1893","Ravensburger Almanya’da Reversi’yi piyasaya sürer"],["Meiji dönemi","Japon kitapları oyunu genpei-go adıyla tanıtır"],["1973","Japonya’da Othello takımları satışa çıkar"],["1977","İlk Dünya Othello Şampiyonası Tokyo’da"],["1997","Logistello, dünya şampiyonu Takeshi Murakami’yi 6–0 yener"],["2023","8 × 8 Othello’nun kusursuz oyunda berabere olduğu gösterilir"]]},"mancala":{"title":"Mangala (mankala) nerede doğdu?","lead":"Taşları çukurdan çukura tohum eker gibi dağıttığın bir oyun; Afrika ve Asya’da yüzlerce adla oynanır.","s":["Mankala, bir çukurdaki taşları ya da tohumları alıp sıradaki çukurlara birer birer ektiğin oyunlar ailesinin adıdır. Kelimenin Arapça “nakala” (taşımak) sözcüğünden geldiği söylenir.","Adlar ve kurallar yerden yere değişir — Batı Afrika’da oware, Doğu Afrika’da bao, Türkiye’de mangala, Güneydoğu Asya’da congkak ve yüzlercesi —; iki ya da dört sıralı, istenen sayıda çukurlu.","Çoğu zaman çok eski olduğu söylenir ama kesin kanıtlar sanıldığından yenidir. Tarihi kesin olarak bilinen en eski tahtalar şimdilik, eski Aksum Krallığı’nın Matara ve Yeha (Eritre ve Etiyopya) yerleşimlerinde bulunan, 6.–7. yüzyıllara ait toprak ve taş tahtalardır.","Daha eski örnekler öne sürülmüştür ama o delik sıralarının gerçekten mankala için olup olmadığı belirsizdir ve araştırmacılar ayrı düşer. Güçlü bir görüşe göre oyun Aksum’dan Arabistan’a ve Afrika’nın içlerine yayıldı.","Oynanışın tam anlatımları ancak 17. yüzyıl dolaylarında ortaya çıkar. Atlas’ta mankalayı oware ve mangala dahil sekiz kuralla oynayabilirsin."],"quiz":[["“Mankala”nın dayandığı Arapça sözcük ne demektir?","Taşımak","Tohum","Çukur","Kral"],["Tarihi kesin bilinen en eski mankala tahtaları nerede bulundu?","Eski Aksum Krallığı yerleşimlerinde (Etiyopya ve Eritre)","Roma’daki Kolezyum’da","Çin Seddi’nde","Stonehenge’de"],["Batı Afrika’da oynanan mankala hangisidir?","Oware","Liubo","Tafl","Paçisi"]],"kf":["Bir kuyudaki taşları alıp sonraki kuyulara birer birer bırakarak oynanan “ekme” oyunları ailesi","Tarihi kesin olan en eski tahtalar, 6.–7. yüzyıl dolaylarındaki eski Aksum Krallığı’ndan","İki sıra ya da dört, hazineli ya da hazinesiz: tahta ve kurallar bölgeden bölgeye değişir"],"more":[{"h":"Ekmek","p":["Mangalada kendi tarafından bir kuyu seçip içindeki bütün taşları alır, sonraki kuyulara birer birer bırakırsın. Tarlaya tohum serpmeye benzeyen bu harekete ekme denir.","Batı Afrika’nın oware’si 48 taşla, 12 kuyunun her birine dörder taşla başlar. Son taş rakip kuyuyu iki ya da üç yaparsa o taşları alırsın. Ekmenin nerede biteceğini önceden saymak her şeydir. Oware Atlantik’i aşıp Karayipler’e de ulaştı."],"cap":["Oware’de ekme. Altın halkalı kuyudaki üç taş saat yönünün tersine birer birer dağıtılır; sonuncusu rakip kuyuyu tam 3 yapınca o 3 taş alınır (kırmızı halka)"]},{"h":"İki sıra ve dört sıra","p":["Mangala tahtaları kabaca iki ve dört sıralı olarak ikiye ayrılır. İki sıralılar Batı Afrika’da ve Asya’da yaygındır; dört sıralılar Doğu Afrika’dan kıtanın güneyine kadar uzanır. Tanzanya’nın bao’su 4 sıra × 8 kuyudur; adı Svahilicede düpedüz “tahta” demektir.","Güneydoğu Asya’daki congkak ve sungka gibi bazılarında, iki uçta alınan taşların toplandığı büyük bir kuyu — hazine — bulunur. 20. yüzyılda ABD’de doğan Kalah da hazineli iki sıralı bir oyundur; 2000’de yapılan hesap, altı kuyulu ve dörder taşlı Kalah’ı ilk oyuncunun hep kazandığını gösterdi."],"cap":["Mangala tahtası örnekleri: 2 sıra × 6 (oware vb.), 2 sıra × 7 ve iki uçta birer hazine (Güneydoğu Asya’nın congkak’ı vb.), 4 sıra × 8 (Doğu Afrika’nın bao’su vb.)"]},{"h":"Onu yazıya geçirenler","p":["Mangalayı ayrıntılı anlatan ilk Avrupalı bilginin genellikle İngiliz Thomas Hyde olduğu söylenir. De Ludis Orientalibus’ta (1694) oyunun Arapça adını ve oynanışını verdi.","1836’da Edward W. Lane, Kahire’nin gündelik yaşamını anlattığı kitabında kahvelerde oynanan “mankala”yı kaydetti. Bugün araştırmacılar dünyanın dört bir yanından oyunlar topladı; kaydedilen kural takımları yüzlercedir."],"cap":[]}],"tl":[["6.–7. yy","Aksum’daki yerleşimlerden, tarihi kesin en eski tahtalar"],["1694","Thomas Hyde, De Ludis Orientalibus’ta mangalayı anlatır"],["18.–19. yy","Oware ve benzerleri Atlantik’i aşıp Karayipler’e ulaşır"],["1836","E. W. Lane Kahire’deki mankalayı kaydeder"],["20. yy ortası","Hazineli iki sıralı Kalah ABD’de satışa çıkar"],["2000","Altı kuyulu dört taşlı Kalah’ı ilk oyuncunun kazandığı hesaplanır"]]},"morris":{"title":"Dokuz taş her yerde","lead":"Bir tapınak çatısı, bir Viking gemisi, bir katedralin taş bankı: çizgileri insanların bir arada oturduğu her yere kazındı.","s":["Dokuz taşta herkes, iç içe üç karenin 24 noktasına dokuzar taş koyar; yan yana üç taş, yani “değirmen”, rakipten bir taş alır. İngilizce adı “morris”in dansla ilgisi yoktur: Latince “oyun pulu” anlamındaki merellus’tan geldiği söylenir.","Mısır’daki Kurna tapınağının çatı taşına kazınmış bir tahta, sık sık MÖ 1400 dolaylarından en eski örnek diye anılır. Ama araştırmacı Friedrich Berger aynı kazımaların arasında Kıpti haçları olduğunu fark etti ve tarihlenemeyeceklerini söyledi. Kesin örnekler Roma döneminde başlar.","Norveç’teki 900 dolaylarına ait Gokstad gemisinde bir tahta güverte tahtasına oyulmuştur. İngiltere’de Canterbury, Salisbury gibi katedrallerin avlu taş banklarında da tahtalar kalmıştır.","X. Alfonso’nun 1283 tarihli Oyunlar Kitabı onu zarla oynanırken bile gösterir. Shakespeare Bir Yaz Gecesi Rüyası’nda yağmurların “dokuz taş”ı çamurla doldurduğunu yazar: köy çayırına kazılmış bir tahta.","1996’da Alman Ralph Gasser bilgisayarla bütün konumları taradı ve iki taraf da kusursuz oynarsa oyunun berabere bittiğini kanıtladı. İki insan arasında yine de çok iyi bir oyundur."],"quiz":[["“Morris” adının nereden geldiği söylenir?","Latince “oyun pulu”ndan","Bir İngiliz dansından","Bir kişi adından","Bir gemi adından"],["Araştırmacılar Kurna tapınağındaki tahtalar için ne dedi?","Tarihlenemezler","Altından yapılmışlar","Çin’den gelmişler","Bir imparatora aitmişler"],["1996’da bilgisayar neyi kanıtladı?","Kusursuz oyunda beraberlik","Başlayan hep kazanır","İkinci hep kazanır","Sekiz taş yeter"]],"kf":["İç içe üç karenin 24 noktasına dokuzar taş; üçü bir sıraya gelince rakipten bir taş alınır","Roma döneminden beri tahtası insanların toplandığı her yere oyuldu: gemi güvertelerine, katedral sıralarına","1996’da tüm konumlar bilgisayarla incelendi: kusursuz oyunda beraberlik"],"more":[{"h":"Koy, sür, uç","p":["Oyun üç aşamada ilerler. Önce oyuncular sırayla dokuz taşını boş noktalara koyar. Hepsi konunca, bir çizgi boyunca komşu boş noktaya her seferinde bir taş sürülür.","Bir çizgi üzerinde üç taşını sıraya dizersen “değirmen” olur ve rakibin bir taşını tahtadan alırsın. Yaygın bir kurala göre üç taşı kalan oyuncu herhangi bir boş noktaya “uçabilir”. İki taşı kalan ya da hamle yapamayan kaybeder."],"cap":["Bir dokuz taş tahtası. Beyaz dış kenarda değirmen kurdu (altın) ve bir siyah taş alabilir (kırmızı çarpı)"]},{"h":"Üç taştan on ikiye","p":["Aile, taş sayısına göre adlandırılır. Üçer taşlı oyun, XOX’a yakın küçük bir tahtadır. Altışar taşlı oyun iç içe iki kareli bir tahta kullanır.","On ikişer taşlı oyun, dokuz taş tahtasına çapraz çizgiler ekler. Güney Afrika’da morabaraba denir; sığır güden çocukların onu toprağa çizdiği anlatılır, bugün turnuvaları bile vardır."],"cap":["Tahtaların karşılaştırması. Sayı her oyuncunun taşıdır: üç, altı, dokuz ve on iki taş"]},{"h":"Bir satranç şampiyonu ve bir bilgisayar","p":["Dünya satranç şampiyonu Emanuel Lasker de bu oyuna tutulanlardandı. Brettspiele der Völker (1931) kitabında, oyuncu başına on taşlı ve bütün taşlar konmadan da sürülebilen bir sürüm önerdi.","1996’da İsviçreli Ralph Gasser, oyun sonlarının tam tablolarını açılıştan başlayan bir aramayla birleştirerek, iki taraf da kusursuz oynarsa dokuz taşın berabere bittiğini gösterdi. Tahtada yalnızca 24 nokta vardır ama konumların sayısı milyarları bulur."],"cap":[]}],"tl":[["Roma dönemi","İmparatorluk boyunca taşlara tahtalar oyulur (ilk kesin örnekler)"],["y. 900","Norveç’teki Gokstad gemisinin güverte tahtasına bir tahta oyulur"],["1283","X. Alfonso’nun Oyunlar Kitabı dokuz taşı resmeder"],["Orta Çağ","İngiliz katedrallerinin revak sıralarına tahtalar oyulur"],["1590’lar","Shakespeare’in Bir Yaz Gecesi Rüyası çamurla dolmuş bir tahtadan söz eder"],["1931","Lasker, Brettspiele der Völker’de yeni bir sürüm önerir"],["1996","Gasser kusursuz oyunda beraberliği kanıtlar"]]},"patolli":{"title":"Patolli, Aztek fasulye yarışı","lead":"Haç biçimli bir tahta ve zar yerine fasulyeler: bahisleri öyle kızışan bir oyun ki İspanyollar onu yasakladı.","s":["Patolli, Meksika Aztekleri’nin bir yarış oyunuydu. Adı fasulye demektir: Bir yüzü işaretli ya da delikli beş kırmızı fasulye atılır, görünen işaret sayısı kadar, hasır ya da yere çizilmiş haç biçimli yolda ilerlenirdi.","16. yüzyılda bölgeyi yazan Diego Durán, oyuncuların atıştan önce tütsü yaktığını, fasulyelere dua ettiğini ve oyunların tanrısı Macuilxochitl’den zafer dilediğini anlatır.","Soylular mücevher, pelerin, hatta kendilerini ortaya koyar; kaybedenlerin bazıları köle olurdu. İmparator Moctezuma’nın soyluların oyununu izlediği de anlatılır.","İspanyol rahipler, bahisten ve eski tanrılara edilen dualardan hoşlanmadıkları için patolliyi yasakladı, hasırları kırdı, fasulyeleri yaktı; bu yüzden pek takım kalmadı. Yine de taş zeminlere ve kayalara kazınmış tahtalar Teotihuacan’da ve Maya yerleşimlerinde, 1977’de de Jalisco’daki kaya resimleri arasında bulundu.","Taşların dolaştığı haç biçimli tahta, Hindistan’ın paçisisine çok benzer. 1878’de İngiliz E. B. Tylor Asya kökenini savundu; bugün çoğu kişi ikisinin ayrı ayrı doğduğunu düşünür."],"quiz":[["Patollide zar yerine ne atılırdı?","İşaretli fasulyeler","Hayvan kemikleri","Kabuklar","Tahta çubuklar"],["Kayıtlara göre patolli neden yasaklandı?","Bahis ve eski tanrılara dualar","Tahta çok büyüktü","Fasulyeler pahalıydı","Kral kaybetti"],["Patolli tahtası hangi oyuna çok benzer?","Paçisi","Go","Dama","Mangala"]],"kf":["Bir Aztek yarış oyunu: işaretli beş fasulye atılır, taşlar haç biçimli bir tahtada ilerletilir","Bahis ve tanrılara duayla iç içe olduğu için İspanyol keşişlerce yasaklandı","Hindistan’ın paçisisine şaşırtıcı biçimde benzer, ama ikisinin ayrı ayrı doğduğu düşünülür"],"more":[{"h":"52 karelik haç biçimli yol","p":["Patolli tahtası kumaşa, hasıra ya da taş zemine çizilmiş haç biçimli bir yoldur. Yeniden kuruluşlar genellikle dört kolun her birine iki sıra kare verir; ortadaki dört kareyle birlikte 52 eder.","Elli iki, Aztek takviminin bir tam devrinin yıl sayısıdır da; bu yüzden bazı araştırmacılar tahtada takvimin ya da akıp giden zamanın bir resmini görür. Taşlar yol boyunca bir tur dolaştırılır, eve ilk dönen kazanırdı."],"cap":["Sık yapılan bir yeniden kuruluşa göre patolli tahtası: dört kolda altışar karelik iki şerit ve ortadaki dört kare, toplam 52. Kol uçlarındaki kırmızı karelerin özel olduğu düşünülür"]},{"h":"Beş fasulye","p":["Zar yerine, bir yüzünde delik ya da işaret bulunan beş fasulye atılır, kaç işaret görünürse o kadar kare gidilirdi. Beş işaretin birden gelmesi 32 atışta yalnızca bir kezdir.","Atıştan önce fasulyelerle konuşulduğu ve oyunların tanrısı Macuilxochitl’e seslenildiği anlatılır. 16. yüzyıla ait Magliabechiano Kodeksi, tanrının gözetiminde bir patolli tahtası başında toplanmış insanları gösterir."],"cap":["Beş fasulyeden kaçının işaretli yüzü yukarı düştüğü (0–5) ve ne sıklıkla (32’de), her biri iki yüze eşit olasılıkla düşerse"]},{"h":"Paçisinin benzeri","p":["Haç biçimli tahtanın çevresini dolaşan taşlar, atılan nesnelerden kaçının yüzü yukarı düştüğüne göre ilerleme: patolli ile Hindistan’ın paçisisi ya da çauparı şaşırtıcı ölçüde benzer. 1878’de İngiliz antropolog Tylor bunun rastlantı olmadığını, oyunun Asya’dan geldiğinin işareti olduğunu savundu.","Ama okyanusları aşan böyle bir geçişin kanıtı bulunamadı. Bugün çoğu araştırmacı, farklı yerlerdeki insanların aynı fikirlere — dönen bir yol ve atılacak nesneler — kendi başlarına vardığını düşünür."],"cap":["Hindistan’da çauparı gösteren bir resim (1694–95): taşlar, patollide olduğu gibi haç biçimli bir tahtanın çevresini dolaşır"]}],"tl":[["Teotihuacan dönemi","Taş zeminlere haç biçimli tahtalar oyulur"],["1519–21","İspanya Aztekleri fetheder"],["16. yy","Magliabechiano Kodeksi patolliyi ve Macuilxochitl’i resmeder"],["y. 1577","Sahagún, Floransa Kodeksi’nde patolliyi kaydeder"],["y. 1581","Durán duaları ve bahisleri anlatır"],["1878","Tylor Asya kökeni görüşünü ileri sürer"],["1977","Jalisco’daki kaya resimleri arasında bir tahta bulunur"]]},"xiangqi":{"title":"Şiangçi’nin nehri ve topu","lead":"Ortada bir “nehir” ve atlayarak alan bir top: Çin satrancı bugünkü biçimini ne zaman aldı?","s":["Şiangçi (xiangqi), 9×10 bir ızgaranın noktalarında oynanan Çin satrancıdır. Taşlar üzerinde yazı olan yuvarlak disklerdir ve satrançtaki gibi karelerin içinde değil, çizgilerin üzerinde hareket eder.","Erken bir ipucu, Tang veziri Niu Sengru’nun (779–847) tuhaf öyküler derlemesi Xuanguai lu’dur. Bir adamın minicik bir orduyu gördüğü rüyada göksel at, general, savaş arabaları ve piyadeler geçer; bir mancınığı andıran ifadeler de vardır. Ama tahta ve hamleler bugünküler değildir.","Bugünkü biçim — 9×10 tahta, nehir ve top — Song hanedanı (960–1279) kayıtlarında görülür. Luoyang’daki bir Kuzey Song mezarında eksiksiz bir taş takımı bulunmuştur.","Nehrin üzerinde çoğu zaman “Chu Nehri, Han Sınırı” yazar; MÖ 3. yüzyılda Xiang Yu’nun Chu’su ile Liu Bang’ın Han’ı arasındaki savaştaki sınırdan gelir. General sarayından çıkamaz ve iki general arada hiçbir taş yokken karşı karşıya gelemez.","Top yalnızca tam bir taşın üzerinden atlayarak alır. Şiangçi Vietnam’da cờ tướng adıyla sevilir; Kore’de ise yakın akrabası janggi’ye dönüşmüştür. Atlas’ta ikisini de oynayabilirsin."],"quiz":[["Şiangçi taşları nerede hareket eder?","Çizgilerin noktalarında","Karelerin içinde","Bir çemberin çevresinde","Altıgenlerde"],["Bugünkü şiangçi hangi hanedanın kayıtlarında görülür?","Song","Han","Ming","Qing"],["Top nasıl alır?","Bir taşın üzerinden atlayarak","Düz bir adım","Çapraz iki adım","Yalnızca nehri geçince"]],"kf":["Çin satrancı: üzerinde yazı olan yuvarlak taşlar 9 × 10 çizgilik bir ızgaranın kesişim noktalarında savaşır","Ortadan bir “nehir” geçer, her tarafın generali için bir “saray” vardır; her taşın kendi alanı vardır","Bugünkü biçimini Song hanedanında aldı; Çin’de ve Vietnam’da hâlâ on milyonlarca kişi oynar"],"more":[{"h":"Nehirli ve saraylı tahta","p":["Her tarafın 16 taşı vardır: bir general, 2 danışman, 2 fil, 2 at, 2 savaş arabası, 2 top ve 5 asker. Kırmızı ve siyah, aynı görevdeki bazı taşları biraz farklı karakterlerle yazar.","General ve danışmanlar saraydan çıkamaz, filler nehri geçemez. Askerler nehri geçene kadar yalnız ileri gider, geçince yana da gidebilir. At, gitmek istediği yönde hemen yanında bir taş varsa sıçrayamaz. Tahtanın kendisi her taşın rolünü belirler."],"cap":["Şiangçi’nin başlangıç dizilişi. Siyah üstte, kırmızı altta. 楚河 漢界 yazısı nehri gösterir; çaprazlı 3 × 3 alanlar saraylardır"]},{"h":"Sıçrayan top","p":["Top normalde araba gibi bir çizgi boyunca istediği kadar gider. Ama taş almak için arada tam bir taş — rengi fark etmez — bulunmalı ve onu atlamalıdır; buna “perde” denir.","Perde olarak taş kullanmak başka hiçbir oyunda olmayan taktikler doğurur. Başta topu orta sütuna getirmek, yani “merkez top”, bugün de en sevilen açılışlardan biridir."],"cap":["Topun alışı: kırmızı top aradaki tam bir taşı — siyah atı — atlayıp ötedeki siyah arabayı alır"]},{"h":"Kayıtlar ve ustalar","p":["Ming hanedanında güzel oyunları ve problemleri toplayan pek çok kitap çıktı. Shiqing yaqu (1570) ve Juzhong mi (1632) bugün hâlâ incelenen klasiklerdir.","20. yüzyılda Hu Ronghua Çin şampiyonasını üst üste on kez kazandı; 1993’te Dünya Şiangçi Federasyonu kurularak uluslararası turnuvalar başladı. Çin’in ve Vietnam’ın parklarında her gün tahtanın çevresinde seyirci halkaları oluşur."],"cap":[]}],"tl":[["9. yy","Niu Sengru’nun Xuanguai lu’sunda general, araba ve at geçer"],["Song (960–1279)","9 × 10 tahta, nehir ve toplu bugünkü biçim kayıtlarda görülür"],["Kuzey Song","Luoyang’daki bir mezara tam bir taş takımı konur"],["1570","Oyun derlemesi Shiqing yaqu"],["1632","Oyun derlemesi Juzhong mi"],["1960’lar–70’ler","Hu Ronghua üst üste on ulusal şampiyonluk kazanır"],["1993","Dünya Şiangçi Federasyonu kurulur"]]},"backgammon":{"title":"Tavla 5000 yaşında mı?","lead":"“En eski tavla” denen tahta ve oyunun gerçek ataları — bir İran sarayından New York kulüplerine.","s":["İran’daki “Yanık Şehir” Şehr-i Suhte’den yaklaşık 5000 yıllık bir tahta, 60 taş ve zarlar çıktı; sık sık en eski tavla diye anılır. Ama hanelerini oyma bir yılanın kıvrımları oluşturur, yirmi kadar — bugünkü oyundan farklı bir biçim.","Tavlanın olası doğrudan atası, 3. ile 6. yüzyıllar arasında ortaya çıkan İran nardıdır. 7.–9. yüzyıllarda yazılmış Orta Farsça bir anlatıya göre vezir Bozorgmehr, Hindistan’dan gönderilen satrancın bilmecesini çözdükten sonra karşılık olarak nardı icat etti.","Roma’nın da üç zarla oynanan bir tahta oyunu vardı, tabula — 3. öyküdeki İmparator Zenon’un talihsiz oyunu. Bu “tavlalar” ailesi bütün Avrupa’ya yayıldı ve Fransız trictrac’ı gibi pek çok akraba doğurdu.","“Backgammon” adı 17. yüzyıl İngiltere’sinde görülür; 1743’te Edmond Hoyle kurallarını ve stratejisini yayımladı.","Son büyük icat olan katlama zarının 1920’lerde New York kulüplerinde doğduğu söylenir. Oyunun ortasında bahsi ikiye katlamayı mümkün kılarak tavlayı, ne zaman bastıracağını kestirmeye dayanan derin bir oyuna çevirdi."],"quiz":[["Şehr-i Suhte tahtasının biçimi nedir?","Yılan kıvrımlarından haneler","Bugünkü tavlayla aynı","Yuvarlak bir disk","Haç"],["Anlatıya göre nardı kim icat etti?","Vezir Bozorgmehr","İmparator Zenon","Edmond Hoyle","X. Alfonso"],["1920’lerde New York’ta doğduğu söylenen nedir?","Katlama zarı","İki zar","24 hane","On beş pul"]],"kf":["Her tarafın on beş pulu, iki zarla 24 hane üzerinde koşar; hepsini önce toplayan kazanır","Doğrudan ataları Pers nardı ve Roma tabulası gibi “tavla” ailesi oyunlarıdır","Katlama küpü ve bilgisayarlar 20. yüzyılda oyuna yeni bir derinlik kattı"],"more":[{"h":"On beş pul ve 24 hane","p":["Tahtada 24 uzun üçgen, yani hane vardır ve her oyuncunun 15 pulu bulunur. İki zar atılır; her sayı için bir pul ya da ikisi için tek bir pul oynanır. Çift gelirse o sayı dört kez oynanır.","Tek duran rakip pulun üzerine gelirsen onu “kırar”, ortadaki bara gönderirsin; o pul rakibin evinden yeniden girmek zorundadır. On beş pulun hepsi evine gelince pulları toplamaya başlarsın; önce bitiren kazanır."],"cap":["Tavlanın başlangıç dizilişi. Beyaz 24’ten 1’e (saat yönünün tersine) ilerler; sağ alttaki 1–6 haneleri onun evidir. Siyah ters yönde ilerler"]},{"h":"Yakınsa vurmak kolay","p":["Tek duran bir pulu vurup vuramamak büyük ölçüde mesafeye bağlıdır. Altı hane uzaktan 36 atıştan 17’si vurur; yedi haneden yalnızca 6’sı.","Bu sayıları bilmek, bir pulun nerede tehlikede olduğunu gösterir. Başlangıçta her oyuncunun bütün pulları eve getirip toplaması için toplam 167 zar sayısı gerekir; güçlü oyuncular kimin önde olduğunu bu “pip sayısı” ile ölçer."],"cap":["Tek duran bir pulu 1–12 hane uzaktan vurabilen atış sayısı: iki zarın 36 sonucundan kaçı (yol kapalı değilse)"]},{"h":"Kulüplerden dünya şampiyonalarına","p":["1743’te İngiltere’de Edmond Hoyle kurallar ve strateji üzerine bir kitap yayımladı. 19. yüzyıl Britanya’sında oyun mobilyalara resmedilecek kadar sevildi; 1920’lerin New York kulüplerinde katlama küpü doğdu.","1964’te Bahamalar’da bir dünya şampiyonası yapıldı, 1970’lerde oyun büyük moda oldu. 1979’da Hans Berliner’in programı dünya şampiyonu Luigi Villa’yı yendi; 1992 dolaylarında kendisiyle oynayarak öğrenen TD-Gammon, en iyi insanlara yakın bir güce ulaştı."],"cap":["İki tavla oyuncusu resmedilmiş bir dolap (Londra, 1861), Morris, Marshall, Faulkner & Co.’nun ilk işlerinden"]}],"tl":[["y. MÖ 3000","Şehr-i Suhte’de yılan biçimli bir tahta, taşlar ve zarlar gömülür"],["y. 3.–6. yy","Pers’te nard ortaya çıkar"],["1743","Hoyle tavla kitabını yayımlar"],["1920’ler","New York’ta katlama küpü doğar"],["1964","Bahamalar’da dünya şampiyonası"],["1979","Berliner’in programı dünya şampiyonunu yener"],["y. 1992","Kendisiyle oynayarak öğrenen TD-Gammon ortaya çıkar"]]},"hex":{"title":"İki kez icat edilen Hex","lead":"Danimarkalı bir şair ve genç bir Amerikalı dâhi, birbirlerinden habersiz aynı oyunu buldu.","s":["Hex’te oyuncular sırayla altıgenlerden oluşan bir eşkenar dörtgene taş koyar; kendi iki karşılıklı kenarını birleştiren kazanır. Hepsi bu.","İlk düşünen Danimarkalı matematikçi ve şair Piet Hein’dı. 1942’de Kopenhag’daki Niels Bohr Enstitüsü’nde tanıttı; o yılın 26 Aralık’ında Politiken gazetesi oyunu “Polygon” adıyla yayımladı ve 50 yapraklık bloknotlar hâlinde satıldı.","1943’te Hein Danimarka’dan ayrılmak zorunda kaldı ve oyun unutuldu. Birkaç yıl sonra, 1948–49’da, Princeton’da lisansüstü öğrencisi John Nash aynı oyunu tamamen bağımsız olarak buldu; arkadaşlarının ona “Nash” dediği anlatılır.","1952’de Parker Brothers oyunu “Hex” adıyla çıkardı; 1957’de Martin Gardner Scientific American’daki köşesinde tanıtarak onu dünyaya duyurdu.","Hex hiçbir zaman berabere bitmez. Nash da ilk oyuncunun her zaman kazanan bir stratejisi olduğunu — ne olduğunu göstermeden — kanıtladı. Büyük tahtalarda o kazanma yolu hâlâ bilinmiyor."],"quiz":[["Hex’te nasıl kazanılır?","Kendi iki kenarını birleştirerek","Bütün taşları alarak","Şahı kuşatarak","Beşli dizerek"],["Hein’ın oyunu Danimarka gazetesinde hangi adla çıktı?","Polygon","Nash","Con-tac-tix","Othello"],["Nash neyi kanıtladı?","İlk oyuncu her zaman kazanabilir","İkinci her zaman kazanır","Hep berabere biter","Tam kazanan hamleleri"]],"kf":["Altıgen hücrelere sırayla taş konur; kendi renginin karşılıklı iki kenarını birleştiren kazanır","Danimarka’da Piet Hein (1942) ve ABD’de John Nash (1948–49) tarafından ayrı ayrı icat edildi","Beraberlik yoktur ve ilk oyuncunun kazandığı kanıtlanmıştır — ama büyük tahtalarda nasıl kazanılacağı bilinmiyor"],"more":[{"h":"Birleştirme oyunu","p":["Tahta, altıgen hücrelerden oluşan bir eşkenar dörtgendir; resmî boyut 11 × 11’dir. Kırmızı üst ve alt kenarları, mavi sol ve sağ kenarları üstlenir; sırayla birer taş koyarlar. Taşlar hiç oynamaz ve alınmaz.","Tahta dolduğunda taraflardan biri mutlaka birleşmiştir. Altıgenler yalnızca bir köşeden temas etmez; bu yüzden rakibin hattının arasından sızamazsın. 1979’da matematikçi David Gale, bu “beraberlik yok” özelliğinin matematiğin ünlü bir sonucuna, Brouwer sabit nokta teoremine denk olduğunu gösterdi."],"cap":["7 × 7 Hex tahtası. Kırmızı üstü ve altı, mavi solu ve sağı birleştirirse kazanır. Altın kenarlı kırmızı taşlar üstle altı birleştirmiş"]},{"h":"Köprüler ve merdivenler","p":["Güçlü oyuncuların en sevdiği araç köprüdür. Taşı bir öncekinin hemen yanına değil bir hücre öteye koyarsan, iki taş iki boş komşu hücreyi paylaşır. Rakip birini kapatırsa ötekini alırsın; yani pratikte zaten birleşiktirler.","Kenarlara yakın yerlerde, kenara ulaşmak için kenar boyunca dizilen “merdivenler” gibi pek çok kalıp bilinir. İlk oyuncunun üstünlüğü çok büyük olduğundan genellikle takas kuralı kullanılır: ilk hamleden sonra ikinci oyuncu o taşı kendi taşı olarak alabilir."],"cap":["“Köprü”. İki kırmızı taş, aradaki iki boş hücreden (kesikli daireler) herhangi biriyle birleşebilir. Mavi birini alırsa kırmızı ötekini alır"]},{"h":"Matematikçilerin oyunu","p":["Nash, ilk oyuncunun kazandığını “strateji çalma” akıl yürütmesiyle kanıtladı: ikinci oyuncunun kazanan bir stratejisi olsaydı ilk oyuncu onu kendine alabilirdi; bu bir çelişkidir. Hiçbir kazandıran hamleyi göstermeyen tuhaf bir kanıttır.","1950’lerde bilgi kuramının babası Claude Shannon, elektrik devresiyle Hex oynayan bir makine yaptı. 2010’larda bilgisayarlar 9 × 9’a kadar bütün tahtaları çözdü, ama resmî 11 × 11 tahta hâlâ çözülmedi."],"cap":[]}],"tl":[["1942","Hein bir Danimarka gazetesinde “Polygon”u yayımlar"],["1948–49","Princeton’daki Nash aynı oyunu bulur"],["1952","Parker Brothers onu “Hex” adıyla satar"],["1950’ler","Shannon elektrikle Hex oynayan bir makine yapar"],["1957","Gardner köşe yazısında tanıtır"],["1979","Gale sabit nokta teoremiyle bağını gösterir"],["2010’lar","9 × 9’a kadar tahtalar bilgisayarla çözülür"]]},"foxgeese":{"title":"Tilki, kazlar ve kralın gümüş taşları","lead":"Bir tilki, çok sayıda kaz: iki tarafın hiç eşit olmadığı bir “av oyunu”nun uzun tarihi.","s":["Tilki ve kazlarda tek bir tilki kazların üzerinden atlayıp onları yer; kazlar ise tilkiyi hareket edemeyecek şekilde kıstırmaya çalışır. İki tarafın kuralları farklıdır; tahta, çizgilerle birleşen 33 noktalı bir haçtır.","Erken bir ipucu, 14. yüzyıl dolaylarında yazılan İzlanda’nın Grettir Destanı’ndaki “halatafl”dır. “Kuyruk tahtası” demektir; kuyruğun tilki kuyruğu olduğu düşünülür. Muhtemelen İskandinav tafl oyunlarının bir koluydu.","İngiltere’de Kral IV. Edward’ın 15. yüzyıl hesap defterlerinde “yaldızlı gümüşten iki tilki ve 26 tazı” satın alındığı yazar: iki takım için taşlar; o zamanlar “tilki ve tazılar” denmiş gibi görünüyor.","Baştaki 13 kazla tilki fazla güçlüydü; bu yüzden daha çok kazla oynama yolları yayıldı. 19. yüzyılda Kraliçe Victoria’nın da bu oyunu sevdiği söylenir.","Aynı haç biçimli tahta tek kişilik peg solitaire için de kullanılır. Nepal’in bagh-chal’ı gibi, bir kaplanın ya da kurdun avını kovaladığı av oyunları dünyanın her yerinde vardır. Atlas’ta hem tilki ve kazları hem de peg solitaire’i oynayabilirsin."],"quiz":[["Halatafl’daki “hala” ne demektir?","Kuyruk","Tilki","Kral","Kar"],["IV. Edward’ın hesaplarında hangi taşlar var?","Gümüş tilkiler ve tazılar","Altın kazlar","Fildişi bir kral","Tahta zarlar"],["Aynı haç tahtasını kullanan tek kişilik oyun hangisi?","Peg solitaire","Sudoku","İskambil falı","Tangram"]],"kf":["33 noktalı haç biçimli bir tahtada bir tilki 13 (sonradan 17) kaza karşı","Tilki atlayarak alır; kazlar tilkiyi kıpırdayamayacak hâle getirirse kazanır","Aynı tahta peg solitaire için de kullanılır; bu tür av oyunları dünyanın her yerinde vardır"],"more":[{"h":"Bire on üç","p":["Tilki çizgiler boyunca bir adım ilerler ve ardındaki nokta boşsa komşu kazın üzerinden atlayarak onu alır; damadaki gibi art arda birkaç kez atlayabilir. Kazlar taş alamaz, birçok kuralda geri de gidemez.","Kazların amacı boşluk bırakmadan saf tutup tilkiyi köşeye sıkıştırmak ve hamlesiz bırakmaktır. On üç kazla tilkinin fazla üstün olduğu söylenir; geri gidemeyen on yedi kazla, iyi oynanırsa kazların kazandığı söylenir."],"cap":["Tilki ve kazlar tahtası: çizgilerle birleşen haç biçimli 33 nokta. On üç kaz üstte durur; tilki (turuncu) hemen önündeki kazı (×) atlayıp ardındaki boş noktaya geçerek alabilir"]},{"h":"Av oyunları ailesi","p":["Az sayıda güçlü taşın çok sayıda zayıf taşı kovaladığı av oyunları her yerde vardır. Nepal’in bagh-chal’ında dört kaplan 5 × 5 tahtada yirmi keçiyi avlar; 2004’te yapılan hesap, kusursuz oyunda beraberlik olduğunu gösterdi.","19. yüzyıl Almanya’sında sevilen asalto aynı haç biçimli tahtayı kullanır: iki subaya karşı yirmi dört asker. Burada subaylar, askerlerin ele geçirmeye çalıştığı bir kaleyi savunur."],"cap":["Sayılarla av oyunları: solda avcılar (turuncu), sağda avlananlar (beyaz). Yukarıdan: tilki ve kazlar (1:13), daha çok kazlı sürüm (1:17), Nepal’in bagh-chal’ı (4:20) ve asalto (2:24)"]},{"h":"Kralın taşlarından peg solitaire’e","p":["İngiltere Kralı IV. Edward’ın (hd. 1461–83) hesap kayıtlarında, tilki ve tazı oyunu için yaldızlı gümüş taşlar satın alındığı yazar. Bu, kralların ve soyluların da eğlencesiydi.","Aynı 33 delikli haç tahta, tek başına oynanan peg solitaire için de kullanılır. 1697 tarihli bir Fransız gravürü bu oyunu oynayan soylu bir hanımı gösterir; peg solitaire’in en eski kayıtlarından biri sayılır."],"cap":[]}],"tl":[["y. 14. yy","İzlanda’nın Grettir Destanı’nda “hala-tafl” geçer"],["15. yy sonu","IV. Edward tilki ve tazı için gümüş taşlar satın alır"],["1697","Bir Fransız gravürü peg solitaire oynayan bir hanımı gösterir"],["19. yy","Kraliçe Victoria’nın oyunu sevdiği anlatılır"],["19. yy","Aynı tahtadaki asalto Almanya’da moda olur"],["2004","Nepal’in bagh-chal’ının kusursuz oyunda berabere olduğu gösterilir"]]},"latrunculi":{"title":"Romalı askerlerin tahtası","lead":"Romalıların tutkuyla oynadığı, adını paralı askerlerden alan bir oyun. Kural kitabı kalmadı; yalnızca şiirler, anekdotlar ve topraktan çıkan tahtalar var.","s":["Ludus latrunculorum, eski Roma’da iki kişiyle oynanan bir savaş oyunuydu. Latrunculi aslında paralı askerler ya da haydutlar demekti ve taşlar askerleri temsil ediyordu.","Taşlar bir ızgara üzerinde hareket eder, iki düşman taş arasında kalan taş alınırdı. 1. yüzyıla ait Laus Pisonis şiiri, ilerleyip geri çekilen taşları ve kuşatılıp kıpırdayamaz hâle gelen bir taşı anlatır.","Filozof Seneca, imparator Caligula tarafından ölüme mahkûm edilen Julius Canus’un hikâyesini anlatır. Yüzbaşı onu almaya geldiğinde Canus latrunculi oynuyordu; taşları saydı ve rakibine, kendisi öldükten sonra kazandığını iddia etmemesini söyledi.","Tahtalar imparatorluğun her yerinde bulunmuştur. Kalelerin ve kentlerin taşlarına oyulmuş ızgaralar yaklaşık 8 × 8’den 12 × 12’ye kadar değişir. İngiltere’de Stanway’deki 1. yüzyıl mezarında cam taşlar hâlâ tahtanın üzerinde dizili duruyordu.","Ayrıntılı bir kural kitabı kalmamıştır; bugünkü kurallar araştırmacıların yeniden kurduğu biçimlerdir. Atlas’taki latrunculi de bunlardan birine dayanır."],"quiz":[["Latrunculi’de bir taş nasıl alınır?","İki taş arasına sıkıştırarak","Üzerinden atlayarak","Zar atarak","Kralı kuşatarak"],["İdama götürülmek üzere alınırken latrunculi oynayan kimdi?","Julius Canus","Sezar","Neron","Çiçero"],["Stanway mezarında tahtanın üzerinde ne kalmıştı?","Cam taşlar","Altın sikkeler","Satranç taşları","İskambil kâğıtları"]],"kf":["Eski Roma’da iki kişiyle oynanan, taşları asker sayılan bir savaş oyunu","İki düşman arasında kalan taş alınır; kıpırdayamayan taşlar da anılır","Kural kitabı yok: şiirlerden, anekdotlardan ve kazılarda çıkan tahtalardan yeniden kurulur"],"more":[{"h":"Sıkıştır ve kuşat","p":["Yeniden kuruluşların en zengin kaynağı 1. yüzyıla ait Laus Pisonis şiiridir. Oyunu bir savaş alanı gibi anlatır: bir taş düşmanı çekmek için ilerler, bir başkası arkasını korur, iki düşman arasında kalan ise kaybedilir.","Şiir, kuşatılıp kıpırdayamayan bir taştan da söz eder; bu yüzden pek çok yeniden kuruluş, sıkıştırarak almanın yanında kıpırdayamayan taşlar için de bir kural koyar. Kuzey Avrupa’nın tafl oyunlarında da çok benzer bir alma vardır."],"cap":["Latrunculi’de taş alma (yeniden kuruluş). Solda: mavi ok gibi ilerleyince beyaz taş iki siyah arasında kalır ve alınır (×). Sağda: dört yanı kapalı beyaz taş hareket edemez"]},{"h":"İki yüzlü tahta","p":["Şair Martialis (1. yüzyıl), bir hediyeye eşlik eden şiirinde, bir yüzünde taşların zara göre ilerlediği, öbür yüzünde iki renkli askerlerin savaştığı bir tahtayı anlatır: tek tahtada bir şans oyunu ve bir akıl oyunu.","Zarlı yüzün, tabula ve tavlanın öncüsü olan “on iki çizgi” adlı yarış oyunu olduğu düşünülür. Müzenin koleksiyonundaki zar kulesi (pyrgus) de Romalıların kullandığı bir araçtır."],"cap":["Martialis’in iki yüzlü tahtasının bir canlandırması: bir yüzde zarla oynanan on iki çizgilik bir yarış, öbür yüzde askerlerin ızgarası"]},{"h":"Topraktan çıkan tahtalar","p":["Romalı askerler oynamak için kalelerinin taşlarına ve zeminlerine ızgaralar oydular. Oyulmuş tahtalar Britanya’da Hadrian Duvarı yakınında, ayrıca Almanya, İspanya ve Kuzey Afrika’da bulundu.","Stanway mezarında (1. yüzyıl ortası) ahşap tahta çürümüştü, ama üstündeki beyaz ve mavi cam taşlar, sanki oyunun ortasındaymış gibi yerlerinde duruyordu. Sahibi belki bir hekimdi: onlarla birlikte tıp aletleri de gömülmüştü."],"cap":["Bir zar kulesi (pyrgus). Romalılar hileyi önlemek için zarları böyle kulelerden atardı"]}],"tl":[["MÖ 1. yy","Varro latrunculi’den söz eder"],["MÖ 1. yy sonu","Ovidius aşk şiirlerinde oyuna değinir"],["1. yy","Laus Pisonis oyunu şiirle anlatır"],["1. yy ortası","Stanway’e taşları dizili bir tahta gömülür"],["1. yy","Seneca, Julius Canus’un anekdotunu anlatır"],["1. yy sonu","Martialis iki yüzlü bir tahtayı yazar"],["1994","Schädler kuralların bir yeniden kuruluşunu yayımlar"]]},"amazons":{"title":"Kendi tahtasını yakan oyun","lead":"1988’de Arjantin’de doğan Amazonlar oyunu, satranç vezirinin hareketini Go’nun alan saymasıyla birleştirir.","s":["Amazonlar, 10 × 10 tahtada, her tarafın dört “amazon”uyla oynanan iki kişilik bir oyundur. 1988’de Arjantinli Walter Zamkauskas tarafından icat edildi.","Bir hamle iki bölümden oluşur. Önce bir amazon satrançtaki vezir gibi yatay, dikey ya da çapraz düz bir çizgide hareket eder; sonra vardığı kareden aynı biçimde bir ok atar. Okun düştüğü kare bir daha asla geçilemez.","Her hamle bir kare daha doldurur ve artık hamle yapamayan oyuncu kaybeder. Beraberlik yoktur.","Oyunun sonlarına doğru oklar tahtayı ayrı odalara böler. O zaman kendine ait boş karesi daha çok olan kazanır; konum Go’daki gibi alan sayılarak değerlendirilir.","Yalnızca ilk hamle için 2.000’den fazla seçenek vardır; bu yüzden oyun bilgisayarlar için bile zordur. Matematikçiler onu inceler ve bilgisayar turnuvalarında bir yarışma dalıdır."],"quiz":[["Amazonlar oyunu hangi ülkede doğdu?","Arjantin","Brezilya","İspanya","Meksika"],["Ok atılan kareye ne olur?","Artık kimse onu geçemez","Bir sonraki hamlede kaybolur","Rakibin taşı olur","Puan getirir"],["Amazonlar’da kim kaybeder?","İlk hamle yapamayan","İlk taş kaybeden","İlk alan kuran","Süresi biten"]],"kf":["1988’de Arjantin’de doğan, 10 × 10 tahtada iki kişilik bir oyun","Amazon vezir gibi hareket eder, vardığı yerden ok atıp bir kareyi yakar","Hamle yapamayan kaybeder; sonda Go’daki gibi alan sayılır"],"more":[{"h":"Hareket et, sonra ok at","p":["Bir amazon, başka bir taşın ya da okun üzerinden geçmedikçe istediği kadar kare ilerleyebilir. Vardığı kareden yine vezir hareketiyle bir ok atar — az önce ayrıldığı kareye bile.","Hiçbir şey alınmaz. Onun yerine her hamle tahtadan bir kareyi kapatır ve rakibin yollarını keser: saldırı da savunma da aynı okla belirlenir."],"cap":["Amazonlar’da bir hamle. Beyaz amazon vezir gibi hareket eder (mavi), vardığı yerden aynı biçimde ok atar (kırmızı). Okun karesi sonsuza dek kapanır"]},{"h":"Odalara bölünen tahta","p":["Oyun ilerledikçe oklar tahtayı odalara böler. Bir odada yalnız bir oyuncunun amazonları varsa, oradaki boş kareler yalnız onundur ve her hamlede bir tanesi harcanır.","O zaman oyun bir saymacaya döner: kullanılabilir karesi çok olan daha uzun hamle yapabilir. Bu, kombinatoryal oyun kuramına çok uygundur; Elwyn Berlekamp ve başkaları Amazonlar’ın oyun sonlarını ayrıntılı inceledi."],"cap":["Oyun sonu (canlandırma). Yanmış karelerden duvarlar tahtayı dört odaya böler: yeşilleri yalnız beyaz, mavileri yalnız siyah kullanabilir. Boş karesi çok olan daha uzun hamle yapabilir"]},{"h":"Dergide doğdu, bilgisayarlar arasında yarışılıyor","p":["Oyunun ilk kez bir Arjantin bulmaca dergisinde yayımlandığı söylenir. Kuralları kısadır ve bir satranç tahtası ile birkaç taş yeter; bu yüzden internet aracılığıyla dünyaya yayıldı.","2.000’den fazla olası ilk hamle bulunduğundan açılış, Go’daki gibi tüm tahtayı görmeyi gerektirir. 2000’lerden beri bilgisayar turnuvalarının bir dalıdır ve programlar birbirleriyle yarışır."],"cap":[]}],"tl":[["1988","Walter Zamkauskas Amazonlar’ı icat eder"],["1990’lar","Oyun internet yoluyla dünyaya yayılır"],["2000","Berlekamp oyun sonları üzerine matematiksel çalışmalar yayımlar"],["2000’ler","Bilgisayar Olimpiyatı’nın bir dalı olur"]]},"loa":{"game":"Lines of Action","title":"Saydığın kadar ilerleyen taşlar","lead":"Lines of Action 1969’da Sid Sackson’ın bir kitabıyla dünyaya çıktı. Taş alarak değil, bütün taşlarını tek bir grupta birleştirerek kazanırsın.","s":["Lines of Action (LOA), 8 × 8 tahtada, her tarafın on iki taşıyla oynanan iki kişilik bir oyundur. Claude Soucie tarafından icat edildi ve 1969’da oyun koleksiyoncusu Sid Sackson’ın A Gamut of Games kitabında tanıtıldı.","Bir taş yatay, dikey ya da çapraz düz bir çizgide ilerler. Ne kadar gideceği, o çizgideki taşların —kendi taşların ve rakibinkiler— sayısına tam olarak eşittir. Her hamle sayıları, dolayısıyla mesafeleri değiştirir.","Kendi taşlarının üzerinden atlayabilirsin ama rakibinkilerin üzerinden asla. Rakip taşın üstüne konarsan onu alırsın.","Amaç, bütün taşlarını yatay, dikey ya da çapraz olarak birbirine değen tek bir grupta birleştirmektir. Taş almak rakibin ordusunu küçültür; bu bazen onun birleşmesine bile yardım eder — ilginç bir tuhaflık.","Kurallar kısa ama ileriyi hesaplamak zordur; bu yüzden oyun uzun zamandır oyun yapay zekâsı araştırmalarında kullanılır. Hollanda’daki Maastricht Üniversitesi’nin programları bilgisayar turnuvalarını defalarca kazandı."],"quiz":[["Bir taşın kaç kare gideceğini ne belirler?","O çizgideki taş sayısı","Zarın sonucu","Şimdiye kadar alınan taş sayısı","Her zaman üç kare"],["LOA’da nasıl kazanılır?","Bütün taşlarını tek bir grupta birleştirerek","Rakibin bütün taşlarını alarak","Tahtanın karşı kenarına ulaşarak","Rakibin şahını alarak"],["LOA’yı 1969’da bir kitapta kim tanıttı?","Sid Sackson","Martin Gardner","Edmond Hoyle","H. J. R. Murray"]],"kf":["8 × 8 tahtada, on ikişer taşla oynanan iki kişilik oyun; Claude Soucie icat etti, 1969’da Sid Sackson’ın kitabında tanıtıldı","Taş, çizgisindeki taş sayısı kadar kare gider; kendi taşlarının üzerinden atlayabilir, rakibinkilerin asla","En çok taş alan değil, bütün taşlarını ilk birleştiren kazanır"],"more":[{"h":"Say, sonra ilerle","p":["Örneğin bir taştan geçen yatay sırada üç taş varsa, o taş bu sıra boyunca tam üç kare gider; ne fazla ne eksik. Yolda kendi taşlarının üzerinden geçebilir, ama arada rakip bir taş varsa o yöne gidemez.","Her taş dört çizginin üzerindedir —bir yatay, bir dikey ve iki çapraz— ve her birinin kendi sayısı vardır. Bir taş oynayınca çevresindeki birkaç çizginin sayısı değişir; böylece tahtadaki “mesafeler” her hamlede yeniden karılır. LOA’yı öngörmeyi bu kadar zorlaştıran budur."],"cap":["okların başladığı siyah taşın gidebileceği yerler. Yatay sırada 3 taş var, bu yüzden 3 kare gider (kendi taşının üzerinden atlamak serbest); dikey sütunda 2 taş var, 2 kare gidip beyaz bir taşı alır. Çaprazda da 3 taş var ama yolu beyaz bir taş kesiyor (×)"]},{"h":"Tek grup kazanır","p":["Taşlar yatay, dikey ya da çapraz olarak birbirine değiyorsa bağlı sayılır. Tek taşı kalan oyuncu da “bağlı”dır; yani fazla taş almak rakibe zaferi bile hediye edebilir.","Bir hamle iki tarafı aynı anda birleştirirse ne olacağı baskıya ve turnuvaya göre değişir. Sackson’ın kitabının ilk baskısı bunu beraberlik, sonraki bir baskı hamleyi yapanın zaferi sayar; bugünkü turnuvaların çoğu beraberlik sayar. Bu Atlas’ın LOA’sında hamleyi yapan kazanır."],"cap":["Kazanan bir konum. Beyaz taşlar (altın kenarlı) çaprazlar dahil birbirine değiyor ve tek bir grup oluşturuyor. Siyahlar hâlâ üç parçaya bölünmüş (kesikli çizgi)"]},{"h":"Bilgisayarların uğruna yarıştığı oyun","p":["Küçük tahtası, kısa kuralları ve derin oyunuyla LOA, oyun yapay zekâsı için bir deneme alanı oldu. Maastricht Üniversitesi’nden Mark Winands’ın yazdığı MIA programı Bilgisayar Olimpiyatı’nı 2003, 2004, 2006 ve 2009’da kazandı; çalışmaları 2004 tarihli doktora tezi Informed Search in Complex Games’te toplandı.","2008’de Winands, LOA’yı küçültülmüş 6 × 6 tahtada çözdü ve kusursuz oyunda ilk oyuncunun (Siyah) kazandığını gösterdi. Tam 8 × 8 oyunun hâlâ çözülmediği düşünülüyor. İnsanlar da her yıl Mind Sports Olympiad’da düzenlenen bir dünya şampiyonasında karşılaşıyor."],"cap":[]}],"tl":[["y. 1960","LOA’nın Claude Soucie tarafından icat edildiği söylenir"],["1969","Sid Sackson’ın A Gamut of Games kitabında tanıtılır"],["2003","Winands’ın MIA’sı Bilgisayar Olimpiyatı’nı kazanır (ardından 2004, 2006 ve 2009’da da)"],["2004","Winands’ın doktora tezi Informed Search in Complex Games"],["2008","6 × 6 LOA çözülür: ilk oyuncu kazanır"]]},"konane":{"title":"Kara lav ve beyaz mercan oyunu","lead":"Hawaii halkının oynadığı kōnane, Cook’un yolculuğunun anlatısına geçti; 20. yüzyılda ise matematikçiler onu kombinatoryal oyun kuramıyla didik didik etti.","s":["Kōnane, yerli Hawaiililerin iki kişilik bir oyunudur. Siyah ve beyaz taşlar tahtayı boşluksuz, sırayla doldurur; oyuncular rakibin taşlarının üzerinden atlayarak taş alır.","Eskiden siyah taşlar lavdan, beyazlar ise mercan parçalarındandı. Papamū denen tahta, yüzeyine çukurlar oyulmuş büyük, düz bir taştı. Oyunun Hawaii yaratılış ilahisi Kumulipo’da bile geçtiği söylenir.","Önce Siyah kendi taşlarından birini kaldırır, sonra Beyaz bitişikteki bir taşı kaldırır. Böylece açılan iki delik, atlamaların başlangıç noktasıdır.","Her hamle bir taş almadır. Taş yatay ya da dikey olarak bitişikteki rakip taşın üzerinden atlar ve arkasındaki boş kareye konar. Düz gittiği sürece atlamaya devam edebilir.","Alacak taşı kalmayan kaybeder; beraberlik yoktur. Bu yalın yapı, sonradan matematikçilerin ilgisini çekti."],"quiz":[["Kōnane’nin eski beyaz taşları neden yapılırdı?","Mercandan","Fildişinden","Beyaz mermerden","Hayvan kemiğinden"],["Kōnane’de kim kaybeder?","Alacak taşı kalmayan","Bütün taşları alınan","Tahtanın kenarına ilk varan","Elinde tek taş kalan"],["Art arda atlarken ne yapılamaz?","Yolda yön değiştirmek","Bir hamlede birden fazla taş almak","Yarıda durmak","Kendi taşının yanına konmak"]],"kf":["Yerli Hawaiililerin iki kişilik oyunu; tahtanın her yerine sırayla dizilmiş siyah (lav) ve beyaz (mercan) taşlarla başlar","Her hamle, yatay ya da dikey olarak bir rakip taşın üzerinden atlayıp onu alır; düz giderek yeniden atlanabilir","Alacak taşı kalmayan kaybeder; matematikçiler oyunu kombinatoryal oyun kuramıyla inceledi"],"more":[{"h":"Atla ve al","p":["Atlamalar yalnızca yatay ya da dikeydir, asla çapraz değil. Bitişikteki rakip taşın arkasındaki kare boşsa taş üzerinden atlayıp oraya konar, atlanan taş tahtadan alınır.","Konduğu yerden yeniden atlayabiliyorsa aynı yönde devam edebilir. Yolda yön değiştiremez, istediği zaman da durabilir. Her hamlede yalnızca bir taş oynar."],"cap":["Beyaz bir taş tek hamlede sağa iki kez atlar ve iki siyah taşı alır (mavi 1 ve 2). Konduğu yerden dönüp aşağı atlayamaz (×)"]},{"h":"İlk iki delik","p":["Taşlarla tıka basa dolu bir tahtada kimse atlayamaz. Bu yüzden oyuna başlayan Siyah, ortadaki dört kareden ya da bir köşeden kendi taşını kaldırır. Ardından Beyaz, bu deliğe yatay ya da dikey olarak bitişik kendi taşını kaldırır.","Yan yana iki delik, ilk konma yerleri olur. Nerede açıldıkları bütün oyunu biçimlendirir."],"cap":["Başlamanın iki yolu. Siyah, ortadaki dört kareden (solda) ya da bir köşeden (sağda) kendi taşını kaldırır (1), sonra Beyaz bitişikteki bir taşı kaldırır (2)"]},{"h":"Taş tahtalar ve 238 kare","p":["James Cook’un üçüncü yolculuğunun anlatısı (1784’te yayımlanan III. cilt), Hawaii’de görülen bir taş oyununu “bizim dama oyunumuza çok benzer” ama daha karmaşık diye anlatır. Yazan, subay James King’dir; ona göre tahta yaklaşık iki ayak uzunluğundaydı ve her sırada on dört olmak üzere 238 karesi vardı.","Sabit bir boyut yoktu: 6 × 7, 9 × 13, 13 × 20 ve başka boyutlarda tahtalar bilinir. Bugün çoğunlukla çift kenarlı kare tahtada oynanır; bu Atlas 6 × 6, 8 × 8 ve 10 × 10 sunar. Hawaii Adası’ndaki Puʻuhonua o Hōnaunau Ulusal Tarihî Parkı’nda taşa oyulmuş papamū’lar hâlâ görülebilir."],"cap":["Tahta boyutlarının karşılaştırması: Cook’un yolculuğunun anlatısında geçen 14 × 17 (238 kare) tahta ve bu Atlas’ta oynanabilen 10 × 10, 8 × 8 ve 6 × 6 tahtalar"]},{"h":"Matematikçilerin keşfettiği oyun","p":["Kōnane’de hamle yapamayan kaybeder ve oyunun sonunda tahta bağımsız parçalara bölünür; bu, Elwyn Berlekamp ve arkadaşlarının kombinatoryal oyun kuramına tam uyar. Michael Ernst 1993’te Berlekamp’la kōnane üzerine kısa bir yazı yazdı, 1995 tarihli makalesinde de pek çok konumun değerini hesapladı.","Başka çalışmalar da geldi: Alice Chan ve Alice Tsai tek sıralı kōnane’yi inceledi (2002); Bob Hearn ise tahta büyüdükçe kimin kazanacağını belirlemenin son derece zorlaştığını (PSPACE-tam) gösterdi. Taş atlatma oyunu, hesaplama kuramının konusu olmuştu."],"cap":[]}],"tl":[["1778","Cook’un gemileri Hawaii’ye varır"],["1784","Cook’un üçüncü yolculuğunun anlatısı yayımlanır; King’in taş oyunu tasviri de içindedir"],["1993","Ernst ve Berlekamp kōnane üzerine kısa bir yazı yazar"],["1995","Ernst’in makalesi “Playing Konane Mathematically”"],["2002","Chan ve Tsai tek sıralı kōnane üzerine sonuçlarını özetler"]]},"peg":{"title":"Bir saray salonunda doğan atlama bulmacası","lead":"Peg solitaire, 17. yüzyılın sonunda XIV. Louis’nin Fransız sarayında oynanıyordu. Çivileri tek tek eksilten bu basit bulmaca o günden beri matematikçileri büyülüyor.","s":["Peg solitaire tek kişilik bir bulmacadır. Tahtanın deliklerini çiviler doldurur, yalnızca bir delik boş kalır.","Bir çivi, yatay ya da dikey olarak komşu çivinin üzerinden atlayıp arkasındaki boş deliğe geçer. Üzerinden atlanan çivi tahtadan alınır.","Amaç, tek çivi kalana dek atlamaya devam etmektir. Onu tam ortada bırakmak kusursuz bitiştir.","İlk sağlam kayıtlar 17. yüzyıl sonu Fransa’sından, XIV. Louis’nin sarayından gelir. 1697’de Mercure galant dergisi tahtayı ve kuralları yayımladı; bir gravür de yanında tahta bulunan soylu bir kadını gösterir.","Kolay görünür ama zordur. Matematikçi Leibniz de ilgilendi; 20. yüzyılda matematikçiler delikleri boyayarak bazı problemlerin neden çözümsüz olduğunu açıkladı."],"quiz":[["Üzerinden atlanan çiviye ne olur?","Tahtadan alınır","Rakibin olur","Yandaki deliğe kayar","Sonraki turda geri gelir"],["İngiliz tahtasında kaç delik vardır?","33","37","45","64"],["Peg solitaire’in ilk sağlam kayıtları nereden gelir?","17. yüzyıl sonunda XIV. Louis’nin Fransız sarayından","Antik Roma hamamlarından","Edo dönemi Japonya’sında bir tapınak okulundan","19. yüzyıl Amerika’sında bir meyhaneden"]],"kf":["Tek kişilik atlama bulmacası: çivilerin üzerinden atlayıp onları alırsın, tek çivi kalırsa kazanırsın","Sağlam kayıtlar 1697 dolayında XIV. Louis’nin sarayında başlar; klasik tahtalar 33 (İngiliz) ve 37 (Avrupa) deliklidir","Delikleri üç renge boyamak, hangi problemlerin çözümsüz olduğunu önceden gösterir"],"more":[{"h":"Atla ve al","p":["Yalnızca yatay ya da dikey atlanır, asla çapraz değil (üçgen gibi çapraz çizgili tahtalar hariç). Her atlama bir çivi eksiltir; 32 çiviyle başlarsan son çiviye 31 atlamada inersin.","Aynı çivi art arda birkaç kez atlayabilir. Böyle bir zinciri tek hamle sayarsak, İngiliz tahtasında “ortadan ortaya” problemi 18 hamlede çözülür. Ernest Bergholt bu çözümü 1912’de buldu; John Beasley 1964’te daha kısasının olamayacağını kanıtladı."],"cap":["İngiliz tahtasında ilk hamle. Orta boşken üstteki çivi alttakinin üzerinden ortaya atlar (mavi); atlanan çivi alınır (×)"]},{"h":"Saray eğlencesinden","p":["Peg solitaire’in kesin tarihi 1697 dolayında XIV. Louis’nin sarayına uzanır. O yılın ağustosunda Mercure galant tahtayı, kuralları ve bazı problemleri anlattı; gravürcü Claude-Auguste Berey de Soubise prensesini yanında bir tahtayla resmetti.","Bastille’e kapatılan bir soylunun bulmacayı can sıkıntısından icat ettiği hikâyesi de ünlüdür, ama doğrulanamayan bir efsanedir. Fransa’da kullanılan 37 delikli tahtanın da 17. yüzyıldan kaldığı söylenir; köşeleri kesik 33 delikli tahtaya ise İngiliz tahtası denir."],"cap":["İki klasik tahta: 33 delikli İngiliz (solda) ve 37 delikli Avrupa (sağda). Boş delik, her birinin alışılmış başlangıç deliğidir"]},{"h":"Üç rengin gösterdiği","p":["Delikleri, renkler çaprazlar boyunca uzanacak şekilde üç renge boyayalım. O zaman yatay ya da dikey art arda üç delik hep üç ayrı renktedir. Bir atlama iki rengin birer çivisini alır, üçüncüye bir çivi ekler; böylece üç rengin sayılarının tek-çift durumu birlikte değişir.","Ortası boş Avrupa tahtasında her renkte 12 çivi vardır: hepsi çift. Her atlama yalnızca “hepsi çift” ile “hepsi tek” arasında gidip gelir; bu yüzden son tek çivinin konumuna — bir renkte 1, diğer ikisinde 0 — asla ulaşılamaz. Bu tahtada ortadan başlayan problemin çözümü yoktur. Aynı denetim İngiliz tahtasında, ortadan başlayınca son çivinin kalabileceği delikleri yalnızca beşe indirir."],"cap":["37 delikli Avrupa tahtası, çaprazlar boyunca üç renge boyanmış. Orta boşken her renkte 12 çivi vardır"]},{"h":"Matematikçilerin oyuncağı","p":["Leibniz’in 1710 tarihli bir notunda bu oyunu tersten, yani atlanmış delikleri yeniden doldurarak oynamayı sevdiğini yazdığı aktarılır. Sondan geriye doğru düşünmek hâlâ temel çözüm yoludur.","Berlekamp, Conway ve Guy’ın Winning Ways (1982) kitabı bulmacayı ayrıntılı inceledi ve “pagoda fonksiyonlarını” tanıttı: her deliğe, hiçbir atlamanın toplamı artıramayacağı bir puan verirsen bazı hedeflerin imkânsız olduğunu kanıtlayabilirsin. 1999’da bir bilgisayar aramasının bütün konumları taradığı söylenir."],"cap":[]}],"tl":[["1697","XIV. Louis’nin sarayında oynanır; ağustos tarihli Mercure galant tahtayı ve kuralları yayımlar"],["1710","Leibniz’in oyunu tersten oynamak üzerine yazdığı söylenir"],["1912","Bergholt İngiliz tahtasında 18 hamlelik bir çözüm bulur"],["1964","Beasley 18 hamleden kısa çözüm olmadığını kanıtlar"],["1982","Winning Ways, pagoda fonksiyonları dahil analizini ortaya koyar"]]},"fanorona":{"title":"Yaklaşarak al, uzaklaşarak al","lead":"Fanorona, Madagaskar’ın ulusal oyunudur. Efsaneye göre bir tahtı belirledi; 21. yüzyılda ise bilgisayarlar, iki taraf da en iyisini oynarsa sonucun beraberlik olduğunu gösterdi.","s":["Fanorona, Madagaskar’da çok yaygın iki kişilik bir oyundur. Yatay, dikey ve çapraz çizgili 9 × 5’lik bir tahtada, her tarafın 22 taşıyla oynanır.","Tahta, Arap dünyası ve Avrupa’da oynanan “alkerk” tahtasından ikisinin yan yana konmuş hâline benzer. Alkerk’in adaya ulaşıp orada kendine özgü bir oyuna dönüştüğü düşünülür.","En büyük özelliği taş alma biçimidir. Rakip taşa doğru gitmek (“yaklaşma”) ya da ondan uzaklaşmak (“uzaklaşma”), o çizgideki rakip taş dizisinin tamamını alır.","Taş almak zorunludur; taş alan taş yön değiştirip almaya devam edebilir. Tek bir hamle tahtayı baştan aşağı değiştirebilir — fanorona’nın heyecanı budur.","Yüzyıllardır sevilen oyunun, bir oyundan kopamadığı için tahtı kaçıran bir prensin efsanesi bile vardır. 2007’de Hollandalı araştırmacılar, iki taraf da en iyisini oynarsa oyunun berabere bittiğini bilgisayarla gösterdi."],"quiz":[["Fanorona tahtası hangi boyuttadır?","9 × 5","8 × 8","7 × 7","6 × 6"],["Fanorona’da taş almanın iki yolu nedir?","Yaklaşma ve uzaklaşma","Atlama ve sıkıştırma","Kuşatma ve itme","Zar ve kura"],["Bilgisayarlar en iyi oyunda neyi gösterdi?","Beraberlik","İlk oyuncunun zaferi","İkinci oyuncunun zaferi","Henüz hiçbir şey bilinmiyor"]],"kf":["Madagaskar’ın iki kişilik oyunu: 9 × 5 tahtada her tarafa 22 taş, başlangıçta yalnızca orta boş","Rakip taşa yaklaşmak ya da ondan uzaklaşmak, o çizgideki bütün diziyi alır","2007’de bilgisayarlar, en iyi oyunda sonucun beraberlik olduğunu gösterdi"],"more":[{"h":"Yaklaşma ve uzaklaşma","p":["Yaklaşmada, varılan noktanın hemen ötesinde rakip taş varsa, o taş ve arkasında boşluksuz dizilmiş bütün rakip taşlar alınır. Uzaklaşma bunun tersidir: başlangıç noktasının hemen arkasındaki rakip taş ve onun arkasına dizilenler alınır.","Tek adım birkaç taşı birden götürebildiği için ordular daha başlangıçtan hızla erir. Bir hamle hem yaklaşmaya hem uzaklaşmaya izin veriyorsa oyuncu birini seçer."],"cap":["İki alma biçimi. Üstte: beyaz sağa bir adım atıp siyah taşa yaklaşır ve ötesindeki üç siyahı alır (yaklaşma). Altta: beyaz sağa giderek siyah taştan uzaklaşır ve arkasındaki iki siyahı alır (uzaklaşma)"]},{"h":"Yan yana iki alkerk tahtası","p":["Tahtada 5 × 9 = 45 nokta vardır; yatay ve dikey çizgilerin yanı sıra her iki noktadan birinden çaprazlar geçer. Taşlar bir çizgi boyunca komşu noktaya birer adım gider. Başta yalnızca orta boş olduğundan ilk hamle her zaman bir taş almadır.","Tahta, birleştirilmiş iki 5 × 5 alkerk tahtasıdır. Alkerk, 10. yüzyıldan bir Arapça kitapta adı geçen eski bir oyundur; fanorona’nın ondan doğduğu düşünülür. Adaya ne zaman ve nasıl ulaştığı belirsizdir; bazı kitaplar 17. yüzyılı anar."],"cap":["Başlangıç dizilişi: 9 × 5 noktada 22’şer siyah ve beyaz taş, yalnızca orta nokta boş. Kesikli kareler, 5 × 5’lik iki alkerk tahtasını gösterir"]},{"h":"Alma zincirleri","p":["Taş alan taş yeniden alabilir. Ama her adım farklı bir yöne gitmeli ve daha önce geçilen bir noktaya dönülmemelidir. Devam edip etmemek oyuncuya kalmıştır.","Böyle bir zincir tutarsa tek hamle rakibin taşlarının neredeyse yarısını götürebilir. Ama kötü bir yerde biterse taş hemen geri alınır."],"cap":["Bir alma zinciri. Beyaz (1) sağa yaklaşıp iki taş alır; (2) yukarı uzaklaşıp iki alır; (3) sola yaklaşıp iki alır. (1)’den sonra sağa devam edemez (×)"]},{"h":"Bir taht ve bilgisayarlar","p":["Efsaneye göre 16. yüzyıl dolaylarında İmerina kralı Ralambo, tahtı eve ilk dönen oğluna bırakmak için hasta numarası yaptı. Büyük oğul Andriantompokoindrindra zor bir fanorona konumundan kopamadı ve küçük oğul Andrianjaka kral oldu. Bir başka anlatıya göre 1895’teki Fransız işgali sırasında kraliçenin tarafı ritüel bir fanorona oyununa güvendi; ikisi de doğrulanamıyor.","2007’de Hollanda’daki Maastricht Üniversitesi’nden Maarten Schadd ve arkadaşları yedi ve daha az taşlı bütün konumları hesapladı ve ispat sayısı aramasıyla başlangıç konumunun berabere olduğunu gösterdi (makale 2008’de çıktı). Hesap tek bir makinede bir haftadan uzun sürdü."],"cap":[]}],"tl":[["y. 16. yy.","Kral Ralambo’nun veraseti ve fanorona efsanesi"],["y. 17. yy.","Fanorona’nın alkerk’ten ne zaman doğduğuna dair bir görüş"],["1895","Fransız işgali sırasında ritüel fanorona oyunu efsanesi"],["2007","Schadd ve arkadaşları bilgisayarla beraberliği gösterir"],["2008","“Best Play in Fanorona Leads to Draw” makalesi"]]},"janggi":{"title":"Nehirsiz bir tahta ve yalnızca bir kez atlayan top","lead":"Kore’de çok sevilen janggi, Çin xiangqi’siyle aynı 9 × 10 tahtayı kullanır — ama nehri kaldırmış ve taşların hareketini büyük ölçüde değiştirmiştir.","s":["Janggi, Kore’de uzun zamandır oynanan iki kişilik bir satranç oyunudur. Çin xiangqi’sinden doğduğu düşünülür; taşlar 9 × 10 çizgilik bir ızgaranın kesişim noktalarına konur.","Xiangqi’den farklı olarak tahtanın ortasında “nehir” yoktur; filler ve askerler her yere gidebilir. General (şah) baştan “sarayının” ortasında durur ve oradan asla çıkamaz.","Taraflar Cho (mavi ya da yeşil) ve Han’dır (kırmızı). Taşlar sekizgendir ve taş ne kadar güçlüyse o kadar büyük yapılır. İlk hamleyi Cho yapar.","Oyundan önce her taraf atlarla fillerin dört diziliminden birini seçer. Önce Han dizer, Cho onu gördükten sonra karar verir; pazarlık daha ilk hamleden önce başlar.","Mat dışında oyun puanla da belirlenebilir. Başlayan Cho 72 puanla başlar; Han 1,5 puanlık “deom” alır ve 73,5 ile başlar. Kaybedilen her taş puanı düşürür."],"quiz":[["Janggi tahtasında ne yoktur?","Ortada bir nehir","Saraylar","Saraylardaki çaprazlar","90 nokta"],["Top hareket etmek için her zaman ne yapmalı?","Tam olarak bir taşın üzerinden atlamalı","Rakip taşın yanında durmalı","Sarayın içinde olmalı","Şah altında olmamalı"],["Puan sayımında ikinci oyuncu Han kaç puan “deom” alır?","1,5","0,5","3","6,5"]],"kf":["Xiangqi’den doğan Kore satrancı: 9 × 10 tahta, ama nehirsiz","Fil bir düz iki çapraz gider; top tam bir taşın üzerinden atlayarak hareket eder ve alır","Her taraf dört at-fil diziliminden birini seçer; puan sayımında Han 1,5 puanlık deom alır"],"more":[{"h":"Nehirsiz tahta ve dört dizilim","p":["Janggi tahtasında xiangqi’deki aynı 9 × 10 nokta vardır ama ortada nehir yoktur. Her sarayda X biçiminde çaprazlar bulunur; general ve muhafızlar sarayın içinde, bu çaprazlar boyunca da birer adım gider. General sarayın tam ortasında başlar.","Dört dizilim, at ve fillerin yer değiştirmesiyle oluşur. Önce Han dizer, Cho onu gördükten sonra seçer. Fillerin içte mi dışta mı durduğu açılıştaki saldırı yollarını değiştirir."],"cap":["Janggi tahtası ve başlangıç konumu. Nehir yok; üstteki ve alttaki saraylarda çaprazlar var. Kesikli halkalar at ve fillerin yer değiştirebileceği noktaları gösterir; üstteki Han ve alttaki Cho farklı dizilimler seçmiş"]},{"h":"At, fil ve kapanan noktalar","p":["At önce düz bir nokta, sonra dışa doğru çapraz bir nokta gider. Fil daha uzağa gider: bir nokta düz, sonra iki nokta çapraz. İkisinde de yol üzerindeki bir noktada duran taş o yönü kapatır.","Xiangqi fili nehri geçemez ve yalnızca iki nokta çapraz gider; janggi fili ise uzun bacaklıdır ve bütün tahtayı dolaşır. Buna karşılık yolu kolayca kapanır."],"cap":["At (solda) bir düz bir çapraz, fil (sağda) bir düz iki çapraz gider. Mavi noktalar gidebilecekleri yerlerdir. Yol üzerindeki bir noktada taş varsa o yön kapanır (×)"]},{"h":"Yalnızca bir kez atlayan top","p":["Top hem gitmek hem almak için aradaki tam bir taşın üzerinden atlamak zorundadır. Arada hiçbir şey yoksa hiç hareket edemez; bu yüzden başlangıç konumunda toplar yerinden kıpırdayamaz.","Ne atlanan ne de alınan taş top olabilir; bu yüzden iki top yalnızca birbirine bakıp durur. Taş almadığında serbestçe giden xiangqi topuyla karşılaştırınca çok daha huysuz bir taştır."],"cap":["Top. Üstte: tam bir askerin üzerinden atlayıp ötesindeki bir noktaya gider ya da arabayı alır (mavi). Ortada: aradaki taş topsa atlayamaz. Altta: top topu alamaz (×)"]},{"h":"Karşı karşıya generaller ve puanlar","p":["İki general arada hiçbir şey olmayan bir çizgide karşı karşıya gelirse buna “bikjang” denir. Bir kurala göre, bu duruma düşen taraf bunu bozmazsa oyun berabere biter. Geleneksel kurallar, şah altında değilken sıra geçmeye de izin verir.","Değerler: araba 13, top 7, at 5, fil 3, muhafız 3, asker 2. Cho toplam 72 puandır, Han deom ile 73,5. Yarım puan sayesinde puanla beraberlik olmaz. Bu Atlas’ın janggi’sinde bir konum üç kez tekrarlanınca ya da 200 hamlede bu puanlar sonucu belirler."],"cap":[]}],"tl":[["Goryeo dönemi","Bir görüşe göre o zaman oynanıyordu (geliş tarihi tartışmalı)"],["18. yy.","Daha büyük tahtalı bir çeşit olan gwangsanghui’nin kayda geçtiği söylenir"],["1895","Stewart Culin’in Korean Games’inde janggi oynayan adamların resmi yer alır"],["2009","İlk uluslararası turnuvanın Çin’in Harbin kentinde yapıldığı söylenir"]]},"pic":{"tlvmirror":"TLV aynası (Doğu Han, Cleveland Sanat Müzesi)"}};
